import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { Move, ZoomIn, ZoomOut } from "lucide-react";
import {
  FOUNDATION_LAYOUT_WIDTH_INCHES,
  FOUNDATION_LAYOUT_DEPTH_INCHES,
  layoutPointInches,
  foundationLayoutFootprint,
  layoutPositionInches,
  layoutItemKey,
  layoutItemFingerprint,
} from "./foundationLayoutModel";
import {
  beginSceneDrag,
  sceneDragCorner,
  commitSceneDrag,
  resolveSceneDragTarget,
  keyboardNudge,
  nudgePatch,
  sceneEditFromDrag,
  sceneEditFromNudge,
  sceneEditCoalesceKey,
  hitTestPlanAll,
} from "./foundationSceneInput";
import {
  createSceneHistory,
  rowsWithPatch,
  sceneLayoutAnchor,
} from "./foundationSceneHistory";
import {
  createSceneSelection,
  beginClickCandidate,
  isClickRelease,
  sceneNodeId,
} from "./foundationSceneSelection";

export default function FoundationLayoutCanvas({
  items = [],
  poles = [],
  walls = [],
  wallCaps = [],
  signageCabinets = [],
  onMoveItem,
  sceneHistory = null,
  sceneSelection = null,
  onDeleteSelection,
}) {
  const boxRef = useRef(null);
  const [zoom, setZoom] = useState(1);
  const dragRef = useRef(null);
  const [preview, setPreview] = useState(null); // {key,x,z} transient only
  const editable = typeof onMoveItem === "function";

  // The full scene the selection model sees — the canvas renders items +
  // poles today, but hit tests, the object tree, cycling, region selects
  // and breadcrumbs all address all five assembly arrays + wall segments.
  const scene = { items, poles, walls, wall_caps: wallCaps, signage_cabinets: signageCabinets };

  // O-040 history seam — an internal store keeps the component
  // self-contained; a mounted editor passes its own via `sceneHistory` for
  // the page's undo UI (see foundationSceneHistory mount notes).
  const internalHistoryRef = useRef(null);
  if (!internalHistoryRef.current) internalHistoryRef.current = createSceneHistory();
  const history = sceneHistory || internalHistoryRef.current;

  // Geometry-CAS reconciliation — every items change that did NOT come
  // through this canvas's recorded strokes detaches the undo chain, so undo
  // can never resurrect stale geometry over an external write.
  useEffect(() => { history.observe(sceneLayoutAnchor(items)); }, [history, items]);

  // O-034 selection seam — same mount shape as the history store: an
  // internal store keeps the component self-contained; a mounted editor
  // passes its own via `sceneSelection` so the object tree / properties
  // panel / breadcrumbs stay in sync (deferred page wiring — see
  // MOUNT-ANCHORS.md).
  const internalSelectionRef = useRef(null);
  if (!internalSelectionRef.current) internalSelectionRef.current = createSceneSelection();
  const selection = sceneSelection || internalSelectionRef.current;
  useSyncExternalStore(selection.subscribe, () => selection.stateVersion);
  const selState = selection.getState();
  const selIds = new Set(selState.ids);

  // Click candidates + marquee run alongside the drag seam: a press records
  // its down point + topmost hit; release travel (< 5px) decides click vs
  // drag — drags never touch selection.
  const pickRef = useRef(null);    // beginClickCandidate record
  const marqueeRef = useRef(null); // {pointerId, clientX, clientY} — plan lives in the store's marquee

  // Selection reconciliation — identity rules mirror the drag target
  // resolver: component/legacy ids survive reorders; positional `index:`
  // ids keep only while the positional row still exists (a vanished one
  // drops, never re-points); minted component ids upgrade in place.
  useEffect(() => { selection.reconcile(scene); }, [selection, items, poles, walls, wallCaps, signageCabinets]);

  const pctW = (inches) => `${(inches / FOUNDATION_LAYOUT_WIDTH_INCHES) * 100}%`;
  const pctD = (inches) => `${(inches / FOUNDATION_LAYOUT_DEPTH_INCHES) * 100}%`;

  const mountedRef = useRef(true);
  useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; dragRef.current = null; pickRef.current = null; marqueeRef.current = null; }; }, []);

  const cancelDrag = (e) => {
    if (e?.pointerId !== undefined && dragRef.current && e.pointerId !== dragRef.current.pointerId) return;
    dragRef.current = null;
    pickRef.current = null;
    marqueeRef.current = null;
    selection.cancelMarquee();
    setPreview(null);
  };

  const focusNode = (id) => {
    // Focus follows a keyboard cycle so the next Tab/arrow keeps walking
    // the tree (and an item's arrows keep nudging the SELECTED row).
    const el = boxRef.current?.querySelector?.(`[data-node-id="${String(id).replace(/"/g, '\\"')}"]`);
    if (el && typeof el.focus === "function") el.focus();
  };

  // Selection keys shared by item elements and the plan container:
  // Tab/arrows cycle (focus follows), Escape clears, Delete/Backspace is a
  // hook point — the store reports it, the consumer's commit path deletes.
  const applySelectionKey = (e) => {
    const result = selection.applyKey(e, scene);
    if (!result) return false;
    e.preventDefault();
    if (result.status === "delete-request") {
      if (typeof onDeleteSelection === "function") onDeleteSelection(selection.entries());
    } else if (result.status === "cycled" && result.id) {
      focusNode(result.id);
    }
    return true;
  };

  const onPointerDown = (e, item, index) => {
    if (!mountedRef.current || e.button !== 0) return;
    if (e.isPrimary === false || dragRef.current) return; // secondary touch must not replace an active gesture
    const rect = boxRef.current?.getBoundingClientRect();
    const point = layoutPointInches(e.clientX, e.clientY, rect);
    if (!point) return;
    // O-034 selection seam — every primary press is a click candidate. The
    // hit test runs at the DOWN point so paint-order topmost wins (a pole
    // over an item selects the pole); whether the press becomes a click or
    // a drag is decided at release travel.
    pickRef.current = beginClickCandidate({
      pointerId: e.pointerId,
      clientX: e.clientX,
      clientY: e.clientY,
      hit: hitTestPlanAll(scene, point)[0] ?? null,
      additive: e.ctrlKey || e.metaKey || e.shiftKey,
    });
    if (!editable) {
      // Read-only still selects — capture so the release resolves.
      try { boxRef.current.setPointerCapture(e.pointerId); } catch { }
      return;
    }
    const fp = foundationLayoutFootprint(item);
    const pos = layoutPositionInches(item);
    if (!fp || !pos.valid) return;
    const key = layoutItemKey(item, index);
    const [kind] = key.split(":");
    // O-039 input seam — the gesture record comes from the shared primitive;
    // pos/point are already validated above so beginSceneDrag cannot fail.
    dragRef.current = beginSceneDrag({
      pointerId: e.pointerId,
      key,
      identityKind: kind,
      legacyIndex: index,
      count: items.length,
      corner: { x: pos.x_inches, z: pos.z_inches },
      grabPoint: point,
      fingerprint: layoutItemFingerprint(item),
    });
    try { boxRef.current.setPointerCapture(e.pointerId); }
    catch { cancelDrag(); return; }
    setPreview({ key, x: pos.x_inches, z: pos.z_inches });
  };

  // Press on the plan background — the marquee seam. Item divs are direct
  // children, so a background press is exactly e.target === the box. A
  // top-hit reachable through the background (pole dots are
  // pointer-events:none; future wall/cap render layers too) records a
  // click candidate instead — drags from an object are not marquees.
  const onPlanPointerDown = (e) => {
    if (!mountedRef.current || e.button !== 0) return;
    if (e.isPrimary === false) return;
    if (e.target !== e.currentTarget) return;
    const point = layoutPointInches(e.clientX, e.clientY, boxRef.current.getBoundingClientRect());
    if (!point) return;
    const additive = e.ctrlKey || e.metaKey || e.shiftKey;
    const hit = hitTestPlanAll(scene, point)[0] ?? null;
    if (hit) {
      pickRef.current = beginClickCandidate({ pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY, hit, additive });
      try { boxRef.current.setPointerCapture(e.pointerId); } catch { }
      return;
    }
    try { boxRef.current.setPointerCapture(e.pointerId); } catch { return; }
    marqueeRef.current = { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY };
    selection.beginMarquee({ point, additive });
  };

  const onPointerMove = (e) => {
    const d = dragRef.current;
    if (d && e.pointerId === d.pointerId) {
      const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
      if (!point) return;
      d.moved = true;
      d.last = sceneDragCorner(d, point);
      setPreview({ key: d.key, x: d.last.x, z: d.last.z });
      return;
    }
    const m = marqueeRef.current;
    if (m && e.pointerId === m.pointerId) {
      const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
      if (point) selection.updateMarquee(point);
    }
  };

  const commitDrag = (e) => {
    const d = dragRef.current;
    const pick = pickRef.current;
    const marquee = marqueeRef.current;
    // Marquee gesture — the rubber-band path resolves entirely here.
    if (marquee && e.pointerId === marquee.pointerId) {
      marqueeRef.current = null;
      try { boxRef.current?.releasePointerCapture(e.pointerId); } catch { }
      if (!mountedRef.current) return;
      const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
      if (point) selection.updateMarquee(point);
      // Release inside the slop = an empty-space click: additive keeps,
      // plain clears. Beyond it, commit the region.
      selection.commitMarquee(scene, { empty: isClickRelease(marquee, e) });
      pickRef.current = null;
      return;
    }
    // Click-candidate gesture with no drag record (read-only press, or a
    // press on a non-draggable top hit) — resolves purely as selection.
    if (pick && e.pointerId === pick.pointerId && (!d || d.pointerId !== pick.pointerId)) {
      pickRef.current = null;
      try { boxRef.current?.releasePointerCapture(e.pointerId); } catch { }
      if (isClickRelease(pick, e)) selection.selectHit(pick.hit, { additive: pick.additive });
      return;
    }
    if (!d || e.pointerId !== d.pointerId) return;
    dragRef.current = null; // clear before release/callback — one commit per gesture
    pickRef.current = null;
    try { boxRef.current?.releasePointerCapture(e.pointerId); } catch { }
    setPreview(null);
    if (!mountedRef.current) return;
    // final corner from the release point itself, not the last move preview
    const point = layoutPointInches(e.clientX, e.clientY, boxRef.current?.getBoundingClientRect());
    if (!point) return;
    // O-039 input seam — commitSceneDrag applies the unchanged-corner and
    // sub-inch-wiggle guards and returns the whole-inch patch; the target
    // resolver re-finds the row (deletion/reorder during gesture) and checks
    // the fingerprint (authoritative change mid-drag).
    const patch = commitSceneDrag(d, point);
    if (!patch) {
      // No move landed. Release inside the click threshold selects the
      // down-point hit; a drag that travelled and returned does NOT
      // deselect — that is the whole point of the travel check.
      if (pick && isClickRelease(pick, e)) {
        selection.selectHit(pick.hit, { additive: pick.additive });
      }
      return;
    }
    // A landed drag never touches selection — multi-selected scenes keep
    // their selection through the move.
    const target = resolveSceneDragTarget(d, items);
    if (!target) return;
    if (typeof onMoveItem !== "function") return;
    // O-040: the whole gesture — begin, every preview move, commit — records
    // as ONE history command carrying the pre-stroke corner as its inverse
    // patch. Anchors are computed as "the scene with only this row's
    // geometry swapped", so an interleaved write to a different row is
    // preserved inside the entry instead of detaching it.
    const edit = sceneEditFromDrag(d, patch);
    const applied = onMoveItem(target.index, patch);
    if (applied === false) return; // refused commit — nothing landed to undo
    if (edit) {
      history.recordEdit({
        ...edit,
        target: { key: d.key, index: target.index },
        label: `Move Foundation ${target.index + 1}`,
        coalesceKey: sceneEditCoalesceKey(edit),
        beforeAnchor: sceneLayoutAnchor(rowsWithPatch(items, target.index, edit.before)),
        afterAnchor: sceneLayoutAnchor(rowsWithPatch(items, target.index, patch)),
      });
    }
  };

  const onKeyDown = (e, item, index) => {
    if (!mountedRef.current || !editable) return;
    // O-039 input seam — keyboardNudge carries the modifier guard, the arrow
    // map and the Shift 12-inch big-step; nudgePatch builds the same patch.
    const delta = keyboardNudge(e);
    if (delta) {
      const fp = foundationLayoutFootprint(item);
      const pos = layoutPositionInches(item);
      if (!fp || !pos.valid) return;
      e.preventDefault();
      e.stopPropagation(); // consumed here — the plan container must not also cycle
      // O-040: consecutive nudges on the same row coalesce into ONE undo
      // command inside the store's burst window — a held arrow key is one
      // stroke, not N history entries.
      const patch = nudgePatch(pos, delta);
      const applied = onMoveItem(index, patch);
      if (applied === false) return; // refused commit — nothing landed to undo
      const edit = sceneEditFromNudge(layoutItemKey(item, index), pos, patch);
      if (edit) {
        history.recordEdit({
          ...edit,
          target: { key: layoutItemKey(item, index), index },
          label: `Move Foundation ${index + 1}`,
          coalesceKey: sceneEditCoalesceKey(edit),
          beforeAnchor: sceneLayoutAnchor(rowsWithPatch(items, index, edit.before)),
          afterAnchor: sceneLayoutAnchor(rowsWithPatch(items, index, patch)),
        });
      }
      return;
    }
    // Non-nudge keys fall through to the selection layer: Tab cycles
    // (focus follows), Escape clears, Delete/Backspace fires the hook.
    if (applySelectionKey(e)) e.stopPropagation();
  };

  const onPlanKeyDown = (e) => {
    if (!mountedRef.current) return;
    if (e.target !== e.currentTarget) return; // item elements handle their own keys first
    applySelectionKey(e);
  };

  const invalidNotes = items.map((item, index) => ({ item, index }))
    .filter(({ item }) => !foundationLayoutFootprint(item) || !layoutPositionInches(item).valid);

  const marquee = selState.marquee;
  const marqueeRect = marquee
    ? {
        x: Math.min(marquee.start.x, marquee.current.x),
        z: Math.min(marquee.start.z, marquee.current.z),
        w: Math.abs(marquee.current.x - marquee.start.x),
        h: Math.abs(marquee.current.z - marquee.start.z),
      }
    : null;

  return (
    <div className="bg-white rounded-sm border border-gray-200 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
        <div>
          <h3 className="text-[13px] font-bold text-gray-900">Layout Canvas</h3>
          <p className="text-[11px] text-gray-400">
            {editable
              ? "Drag a foundation or use arrow keys (Shift for larger steps). Click selects, Ctrl/Shift-click adds, drag empty space to box-select, Tab/arrows cycle, Esc clears."
              : "Foundation positions (read-only). Click to select, drag empty space to box-select."}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap text-[11px] text-gray-600">
          <span className="flex items-center gap-1">
            <Move className="w-3 h-3" aria-hidden="true" /> Move Foundation
          </span>
          <span className="text-gray-400">40ft × 26ft 8in</span>
          <button
            type="button"
            onClick={() => setZoom((z) => Math.max(0.5, +(z - 0.25).toFixed(2)))}
            aria-label="Zoom layout out"
            className="w-6 h-6 flex items-center justify-center rounded-sm border border-gray-300 hover:bg-gray-50"
          >
            <ZoomOut className="w-3 h-3" aria-hidden="true" />
          </button>
          <span className="w-10 text-center">{Math.round(zoom * 100)}%</span>
          <button
            type="button"
            onClick={() => setZoom((z) => Math.min(2, +(z + 0.25).toFixed(2)))}
            aria-label="Zoom layout in"
            className="w-6 h-6 flex items-center justify-center rounded-sm border border-gray-300 hover:bg-gray-50"
          >
            <ZoomIn className="w-3 h-3" aria-hidden="true" />
          </button>
        </div>
      </div>

      <div className="overflow-auto rounded-sm border border-gray-300 bg-gray-50">
        <div
          ref={boxRef}
          tabIndex={0}
          role="group"
          aria-label="Foundation layout plan — Tab or arrows cycle selection"
          data-scene-selection="true"
          onPointerDown={onPlanPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={commitDrag}
          onPointerCancel={cancelDrag}
          onLostPointerCapture={(e) => cancelDrag(e)}
          onKeyDown={onPlanKeyDown}
          className="relative aspect-[3/2] select-none"
          style={{
            width: `${zoom * 100}%`,
            backgroundImage:
              "linear-gradient(to right, rgba(0,0,0,0.06) 1px, transparent 1px), linear-gradient(to bottom, rgba(0,0,0,0.06) 1px, transparent 1px)",
            backgroundSize: "8.333% 12.5%",
          }}
        >
          {items.map((item, index) => {
            const fp = foundationLayoutFootprint(item);
            const pos = layoutPositionInches(item);
            if (!fp || !pos.valid) return null;
            const key = layoutItemKey(item, index);
            const nodeId = sceneNodeId.item(key);
            const isSel = selIds.has(nodeId);
            const isPrimary = selState.primaryId === nodeId;
            const shown = preview && preview.key === key ? { x_inches: preview.x, z_inches: preview.z } : pos;
            return (
              <div
                key={key}
                role={editable ? "button" : undefined}
                tabIndex={editable ? 0 : undefined}
                aria-label={editable ? `Move Foundation ${index + 1}` : undefined}
                aria-pressed={editable ? isSel : undefined}
                data-node-id={nodeId}
                data-selected={isSel ? "true" : undefined}
                data-primary={isPrimary ? "true" : undefined}
                onPointerDown={(e) => onPointerDown(e, item, index)}
                onKeyDown={editable ? (e) => onKeyDown(e, item, index) : undefined}
                className={`absolute flex items-center justify-center border-2 text-[10px] font-semibold ${
                  isSel
                    ? "border-solid border-sky-600 bg-sky-100/70 text-sky-900 z-10"
                    : "border-dashed border-amber-500 bg-amber-100/70 text-amber-800"
                } ${editable ? "cursor-move" : ""} ${item.foundation_type === "pillar" ? "rounded-full" : "rounded-sm"}`}
                style={{
                  left: pctW(shown.x_inches),
                  top: pctD(shown.z_inches),
                  width: pctW(fp.width),
                  height: pctD(fp.depth),
                  transform: `rotate(${item.rotation_degrees || 0}deg)`,
                  touchAction: editable ? "none" : undefined,
                }}
                title={`Foundation ${index + 1}`}
              >
                Foundation {index + 1}
                {isPrimary && editable && [0, 1, 2, 3].map((h) => (
                  <span
                    key={h}
                    data-selection-handle="true"
                    aria-hidden="true"
                    className="absolute w-2 h-2 bg-white border border-sky-700 rounded-[2px]"
                    style={{
                      left: h === 0 || h === 3 ? "-4px" : undefined,
                      right: h === 1 || h === 2 ? "-4px" : undefined,
                      top: h === 0 || h === 1 ? "-4px" : undefined,
                      bottom: h === 2 || h === 3 ? "-4px" : undefined,
                      pointerEvents: "none",
                    }}
                  />
                ))}
              </div>
            );
          })}

          {preview && (
            <div className="absolute left-1 top-1 z-10 rounded-sm bg-amber-50/90 px-1.5 py-0.5 text-[10px] font-semibold text-amber-800" style={{ pointerEvents: "none" }}>
              Move preview - release to apply
            </div>
          )}

          {marqueeRect && (
            <div
              data-marquee="true"
              aria-hidden="true"
              className="absolute border border-sky-500 bg-sky-300/20 z-20"
              style={{
                left: pctW(marqueeRect.x),
                top: pctD(marqueeRect.z),
                width: pctW(marqueeRect.w),
                height: pctD(marqueeRect.h),
                pointerEvents: "none",
              }}
            />
          )}

          {poles.map((pole, index) => {
            const nodeId = sceneNodeId.pole(layoutItemKey(pole, index));
            const isSel = selIds.has(nodeId);
            return (
              <div
                key={layoutItemKey(pole, index)}
                data-node-id={nodeId}
                data-selected={isSel ? "true" : undefined}
                data-primary={selState.primaryId === nodeId ? "true" : undefined}
                className={`absolute w-2.5 h-2.5 rounded-full border ${
                  isSel ? "bg-sky-500 border-sky-800" : "bg-slate-700 border-white"
                }`}
                style={{
                  left: pctW(pole.x_inches || 0),
                  top: pctD(pole.z_inches || 0),
                  transform: "translate(-50%,-50%)",
                  pointerEvents: "none",
                  boxShadow: isSel ? "0 0 0 2px rgba(2,132,199,0.45)" : undefined,
                }}
                title={`Pole ${index + 1}`}
              />
            );
          })}
        </div>
      </div>

      {invalidNotes.map(({ index }) => (
        <p key={index} className="mt-1 text-[11px] text-amber-700">
          Foundation {index + 1} needs valid dimensions/coordinates before placement.
        </p>
      ))}
    </div>
  );
}

// O-039 (CMP-C08) — foundation scene input primitives.
//
// Pure, deterministic helpers that turn raw pointer/keyboard input and plan
// geometry into scene-level decisions: what is under a point, how a drag
// gesture maps to a corner patch, how arrow keys nudge, where a point can
// snap, and what a hit is called. DOM-free — event-shaped plain records go
// in, plain records come out — so the layout canvas, the future
// selection/edit work (O-034/O-035/O-036), undo coalescing (O-040),
// diagnostics click-navigation (O-042) and export labeling (O-043) all share
// one implementation.
//
// Geometry contract (owned by foundationLayoutModel.js /
// foundationAssemblyModel.js — imported read-only):
//   * items carry a TOP-LEFT plan corner in inches (x_inches/z_inches), an
//     unrotated footprint (length_inches x width_inches; diameter x diameter
//     for pillars), and rotation_degrees about the footprint center
//     (CSS-clockwise in the z-down plan).
//   * poles carry a plan POINT in inches (x_inches/z_inches).
//   * walls carry shape.points [{x,z}] plan inches + shape.closed; segment i
//     runs points[i] -> points[(i+1) % n] (last wraps only when closed).
//   * wall_caps / signage_cabinets carry no plan coordinates — they are
//     reference-mounted and are never hit-tested here.
//
// Hit kinds returned by hitTestPlan / hitTestPlanAll:
//   'item-vertex' | 'item-edge' | 'item-face' | 'pole' |
//   'wall-vertex' | 'wall-segment' | 'wall-face'
// Priority inside one object: vertex > edge/segment > face. Across objects
// the caller's layer order applies (default poles > items > walls, matching
// the canvas's DOM paint order where later siblings render on top); each
// collection is walked in REVERSE index order since later rows paint above.

import {
  FOUNDATION_LAYOUT_WIDTH_INCHES,
  FOUNDATION_LAYOUT_DEPTH_INCHES,
  foundationLayoutFootprint,
  layoutPositionInches,
  layoutItemKey,
  layoutItemFingerprint,
} from "./foundationLayoutModel";
import {
  DEFAULT_PLAN_EXTENT,
  planPointOf,
  planFrameForRect,
  planToFrameLocal,
  planViewFromElementRect,
  screenToPlan,
} from "./foundationSceneTransforms";

const fin = (v) => typeof v === "number" && Number.isFinite(v);
const hypot = Math.hypot;

const PLAN_EXTENT = Object.freeze({
  width: FOUNDATION_LAYOUT_WIDTH_INCHES,
  depth: FOUNDATION_LAYOUT_DEPTH_INCHES,
});

// Default tolerances in plan inches. Callers can derive a per-pixel
// tolerance instead: tolInches = pxTolerance / view.scaleX.
export const DEFAULT_HIT_TOLERANCES = Object.freeze({
  edgeInches: 3,
  vertexInches: 4,
  poleInches: 4,
});

// ---------------------------------------------------------------------------
// Pointer normalization (pointer capture / mouse / touch / pen)
// ---------------------------------------------------------------------------

// Canonical pointer record from any event-shaped object: PointerEvent,
// MouseEvent, TouchEvent, or a plain fixture record. Returns null when no
// finite client point can be found. Touch events without clientX/Y fall
// back to the first touch of touches/changedTouches/targetTouches — the
// "numeric fallback" for non-PointerEvent surfaces.
export function normalizeScenePointer(event) {
  if (!event || typeof event !== "object") return null;
  let clientX = event.clientX;
  let clientY = event.clientY;
  if (!fin(clientX) || !fin(clientY)) {
    const lists = [event.touches, event.changedTouches, event.targetTouches];
    for (const list of lists) {
      const t = list && list.length > 0 ? list[0] : null;
      if (t && fin(t.clientX) && fin(t.clientY)) {
        clientX = t.clientX;
        clientY = t.clientY;
        break;
      }
    }
  }
  if (!fin(clientX) || !fin(clientY)) return null;
  const type = typeof event.pointerType === "string" && event.pointerType
    ? event.pointerType
    : typeof event.type === "string" && event.type.startsWith("touch")
      ? "touch"
      : "mouse";
  return {
    pointerId: event.pointerId === undefined ? null : event.pointerId,
    pointerType: type,
    clientX,
    clientY,
    button: fin(event.button) ? event.button : 0,
    buttons: fin(event.buttons) ? event.buttons : 0,
    isPrimary: event.isPrimary !== false,
    shiftKey: event.shiftKey === true,
    ctrlKey: event.ctrlKey === true,
    metaKey: event.metaKey === true,
    altKey: event.altKey === true,
  };
}

// The canvas's primary-press guard, as a named predicate: left button only,
// and a non-primary pointer (second touch) never starts a gesture.
export function isPrimaryScenePress(pointer) {
  const p = pointer && pointer.clientX !== undefined ? pointer : normalizeScenePointer(pointer);
  if (!p) return false;
  return p.button === 0 && p.isPrimary !== false;
}

// One-call input seam: normalize an event and map it to plan inches through
// an element rect. Returns { pointer, point } or null — point mirrors
// layoutPointInches output ({ x_inches, z_inches }).
export function scenePointerToPlan(event, rect, extent = PLAN_EXTENT) {
  const pointer = normalizeScenePointer(event);
  if (!pointer) return null;
  const view = planViewFromElementRect(rect, extent);
  const point = screenToPlan(view, pointer.clientX, pointer.clientY);
  if (!point) return null;
  return { pointer, point };
}

// ---------------------------------------------------------------------------
// Plan-object geometry (shared with hit-testing + diagnostics)
// ---------------------------------------------------------------------------

// Resolved plan geometry for one item row: corner, footprint and the
// rotation-about-center frame. Null when the row cannot be placed — the
// same rows the canvas marks "needs valid dimensions/coordinates" are also
// not hit-testable.
export function itemPlanGeometry(item) {
  const fp = foundationLayoutFootprint(item);
  const pos = layoutPositionInches(item);
  if (!fp || !pos.valid) return null;
  const frame = planFrameForRect({
    corner: { x: pos.x_inches, z: pos.z_inches },
    size: fp,
    rotationDegrees: fin(item?.rotation_degrees) ? item.rotation_degrees : 0,
  });
  if (!frame) return null;
  return {
    corner: { x: pos.x_inches, z: pos.z_inches },
    size: { width: fp.width, depth: fp.depth },
    center: { x: frame.cx, z: frame.cz },
    frame,
    circular: item?.foundation_type === "pillar",
  };
}

// Wall outline as finite plan points (invalid vertices dropped, indices
// preserved via the returned `points` + `indices` pair) plus the closed flag
// — mirrors the assembly model's segEndpoints rule (closed needs >= 3 pts).
export function wallPlanGeometry(wall) {
  const raw = wall?.shape?.points;
  if (!Array.isArray(raw) || raw.length === 0) return null;
  const points = [];
  const indices = [];
  raw.forEach((p, i) => {
    const q = planPointOf(p);
    if (q) { points.push(q); indices.push(i); }
  });
  if (!points.length) return null;
  return { points, indices, closed: wall?.shape?.closed === true && points.length >= 3 };
}

// ---------------------------------------------------------------------------
// Hit testing
// ---------------------------------------------------------------------------

const labelFor = (collection, index) => {
  switch (collection) {
    case "items": return `Foundation ${index + 1}`;
    case "poles": return `Pole ${index + 1}`;
    case "walls": return `Wall ${index + 1}`;
    default: return `Object ${index + 1}`;
  }
};

const baseHit = (kind, collection, index, obj, point, extra) => ({
  kind,
  collection,
  index,
  key: layoutItemKey(obj, index),
  componentId: obj?.component_id ?? null,
  distance: 0,
  point: { x: point.x, z: point.z },
  label: labelFor(collection, index),
  ...extra,
});

// Edge/corner naming uses screen-style compass directions over the z-down
// plan: 'n' is the smaller-z edge (top of screen), 'w' the smaller-x edge.
const EDGE_NAMES = ["n", "e", "s", "w"];
const CORNER_NAMES = { "-1,-1": "nw", "1,-1": "ne", "1,1": "se", "-1,1": "sw" };

function hitItem(item, index, p, tol) {
  const g = itemPlanGeometry(item);
  if (!g) return null;

  if (g.circular) {
    const r = Math.min(g.size.width, g.size.depth) / 2;
    const d = hypot(p.x - g.center.x, p.z - g.center.z);
    if (Math.abs(d - r) <= tol.edgeInches) {
      return baseHit("item-edge", "items", index, item, p, {
        edge: "rim",
        distance: Math.abs(d - r),
      });
    }
    if (d <= r) return baseHit("item-face", "items", index, item, p, { distance: 0 });
    return null;
  }

  const local = planToFrameLocal(g.frame, p);
  if (!local) return null;
  const hw = g.size.width / 2;
  const hd = g.size.depth / 2;
  const sx = local.lx >= 0 ? 1 : -1;
  const sz = local.lz >= 0 ? 1 : -1;

  // Vertex: euclidean distance to the nearest corner.
  const cdx = Math.abs(local.lx) - hw;
  const cdz = Math.abs(local.lz) - hd;
  const cornerDist = hypot(cdx, cdz);
  if (cornerDist <= tol.vertexInches) {
    return baseHit("item-vertex", "items", index, item, p, {
      corner: CORNER_NAMES[`${sx},${sz}`],
      distance: cornerDist,
    });
  }

  // Edge: perpendicular distance to the nearest side, measured inside OR
  // outside the rect (an edge stays grabbable from either side), as long as
  // the point sits within the edge's span (corners already handled above).
  const dists = [
    { edge: "n", d: Math.abs(local.lz + hd) },
    { edge: "s", d: Math.abs(local.lz - hd) },
    { edge: "w", d: Math.abs(local.lx + hw) },
    { edge: "e", d: Math.abs(local.lx - hw) },
  ];
  dists.sort((a, b) => a.d - b.d);
  const near = dists[0];
  const inSpan = near.edge === "n" || near.edge === "s"
    ? Math.abs(local.lx) <= hw + tol.vertexInches
    : Math.abs(local.lz) <= hd + tol.vertexInches;
  if (near.d <= tol.edgeInches && inSpan) {
    return baseHit("item-edge", "items", index, item, p, { edge: near.edge, distance: near.d });
  }

  const inside = Math.abs(local.lx) <= hw && Math.abs(local.lz) <= hd;
  if (inside) return baseHit("item-face", "items", index, item, p, { distance: 0 });
  return null;
}

function hitPole(pole, index, p, tol) {
  const q = planPointOf({ x: pole?.x_inches, z: pole?.z_inches });
  if (!q) return null;
  const d = hypot(p.x - q.x, p.z - q.z);
  if (d > tol.poleInches) return null;
  return baseHit("pole", "poles", index, pole, p, { distance: d, center: q });
}

const distToSegment = (p, a, b) => {
  const vx = b.x - a.x;
  const vz = b.z - a.z;
  const len2 = vx * vx + vz * vz;
  if (len2 === 0) return { d: hypot(p.x - a.x, p.z - a.z), t: 0, projection: { x: a.x, z: a.z }, degenerate: true };
  let t = ((p.x - a.x) * vx + (p.z - a.z) * vz) / len2;
  t = Math.max(0, Math.min(1, t));
  const px = a.x + t * vx;
  const pz = a.z + t * vz;
  return { d: hypot(p.x - px, p.z - pz), t, projection: { x: px, z: pz }, degenerate: false };
};

// Even-odd ray cast. Deterministic on degenerate (collinear/zero-area)
// outlines — they report no face, matching their zero enclosed area.
const pointInPolygon = (p, pts) => {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i, i += 1) {
    const a = pts[i];
    const b = pts[j];
    if ((a.z > p.z) !== (b.z > p.z) &&
      p.x < ((b.x - a.x) * (p.z - a.z)) / (b.z - a.z) + a.x) {
      inside = !inside;
    }
  }
  return inside;
};

function hitWall(wall, index, p, tol) {
  const g = wallPlanGeometry(wall);
  if (!g) return null;
  const pts = g.points;
  const segs = Array.isArray(wall?.shape?.segments) ? wall.shape.segments : [];

  // Vertex pass — nearest valid authored point within tolerance.
  let best = null;
  for (let i = 0; i < pts.length; i += 1) {
    const d = hypot(p.x - pts[i].x, p.z - pts[i].z);
    if (d <= tol.vertexInches && (!best || d < best.distance)) {
      best = baseHit("wall-vertex", "walls", index, wall, p, {
        vertexIndex: g.indices[i],
        distance: d,
      });
    }
  }
  if (best) return best;

  // Segment pass — assembly contract: segment i = points[i] -> points[i+1],
  // with points[n-1] -> points[0] only when closed. Degenerate (zero-length)
  // segments are skipped here; their endpoints remain reachable as vertices.
  const segCount = g.closed ? pts.length : pts.length - 1;
  for (let i = 0; i < segCount; i += 1) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const r = distToSegment(p, a, b);
    if (r.degenerate) continue;
    if (r.d <= tol.edgeInches && (!best || r.d < best.distance)) {
      best = baseHit("wall-segment", "walls", index, wall, p, {
        segmentIndex: i,
        segmentComponentId: segs[i]?.component_id ?? null,
        t: r.t,
        projection: r.projection,
        distance: r.d,
      });
    }
  }
  if (best) return best;

  if (g.closed && pointInPolygon(p, pts)) {
    return baseHit("wall-face", "walls", index, wall, p, { distance: 0 });
  }
  return null;
}

const HITTERS = { pole: hitPole, item: hitItem, wall: hitWall };
const COLLECTION_OF = { pole: "poles", item: "items", wall: "walls" };

// All hits under a plan point, topmost first. `scene` = { items, poles,
// walls }. `opts.order` lists layer names ('pole'|'item'|'wall') topmost
// first; default matches the canvas paint order (poles render last/on top).
export function hitTestPlanAll(scene, point, opts = {}) {
  const p = planPointOf(point);
  if (!p) return [];
  const tol = { ...DEFAULT_HIT_TOLERANCES, ...(opts.tolerances || {}) };
  if (fin(opts.edgeInches)) tol.edgeInches = opts.edgeInches;
  if (fin(opts.vertexInches)) tol.vertexInches = opts.vertexInches;
  if (fin(opts.poleInches)) tol.poleInches = opts.poleInches;
  const order = Array.isArray(opts.order) && opts.order.length ? opts.order : ["pole", "item", "wall"];
  const hits = [];
  for (const layer of order) {
    const rows = scene?.[COLLECTION_OF[layer]];
    const hitter = HITTERS[layer];
    if (!Array.isArray(rows) || !hitter) continue;
    for (let i = rows.length - 1; i >= 0; i -= 1) {
      const hit = hitter(rows[i], i, p, tol);
      if (hit) hits.push(hit);
    }
  }
  return hits;
}

// The single topmost hit, or null (nothing hit / invalid point). Callers
// distinguish empty-plan from off-plan with classifyPlanPoint.
export function hitTestPlan(scene, point, opts = {}) {
  const hits = hitTestPlanAll(scene, point, opts);
  return hits.length ? hits[0] : null;
}

// 'inside' | 'outside' | 'invalid' — the canvas-vs-outside distinction
// (deselect vs clamp) without conflating it with a miss.
export function classifyPlanPoint(point, extent = PLAN_EXTENT) {
  const p = planPointOf(point);
  if (!p) return "invalid";
  const w = fin(extent?.width) ? extent.width : DEFAULT_PLAN_EXTENT.width;
  const d = fin(extent?.depth) ? extent.depth : DEFAULT_PLAN_EXTENT.depth;
  return p.x >= 0 && p.x <= w && p.z >= 0 && p.z <= d ? "inside" : "outside";
}

// Human label for a hit — the "labels" half of CMP-C08 for future
// selection/status surfaces. Returns null for a null hit.
export function hitLabel(hit) {
  if (!hit || typeof hit !== "object") return null;
  switch (hit.kind) {
    case "item-vertex": return `${hit.label} ${hit.corner} corner`;
    case "item-edge": return `${hit.label} ${hit.edge} edge`;
    case "item-face": return hit.label;
    case "pole": return hit.label;
    case "wall-vertex": return `${hit.label} vertex ${hit.vertexIndex + 1}`;
    case "wall-segment": return `${hit.label} segment ${hit.segmentIndex + 1}`;
    case "wall-face": return `${hit.label} interior`;
    default: return hit.label ?? null;
  }
}

// Label for a scene row without a hit-test — numeric-fallback lists and
// typed-coordinate pickers label rows the same way the canvas does.
export function sceneObjectLabel(collection, index) {
  return labelFor(collection, index);
}

// ---------------------------------------------------------------------------
// Drag primitives (the layout canvas's gesture seam)
// ---------------------------------------------------------------------------

// Begin a corner drag. `corner` is the item's authored top-left plan corner
// ({x,z}); `grabPoint` is the pointer's plan position ({x,z} or
// {x_inches,z_inches}). Produces the same record shape the canvas stores:
// { pointerId, key, identityKind, legacyIndex, count, corner, grab,
//   fingerprint, moved }.
export function beginSceneDrag({ pointerId, key, identityKind, legacyIndex, count, corner, grabPoint, fingerprint } = {}) {
  const c = planPointOf(corner);
  const g = planPointOf(grabPoint);
  if (!c || !g) return null;
  return {
    pointerId,
    key,
    identityKind,
    legacyIndex,
    count,
    corner: { x: c.x, z: c.z },
    grab: { dx: g.x - c.x, dz: g.z - c.z },
    fingerprint,
    moved: false,
  };
}

// The dragged corner for a live plan point (pointer minus grab offset).
export function sceneDragCorner(drag, planPoint) {
  const p = planPointOf(planPoint);
  if (!drag || !p || !fin(drag?.grab?.dx) || !fin(drag?.grab?.dz)) return null;
  return { x: p.x - drag.grab.dx, z: p.z - drag.grab.dz };
}

// Convert a release point into the committed patch, or null when the
// gesture resolves to the original corner. Exactly the canvas's rule:
// unchanged raw corner -> null; sub-inch wiggle that rounds back to the
// same corner -> null; otherwise whole-inch { x_inches, z_inches }.
export function commitSceneDrag(drag, releasePlanPoint) {
  const raw = sceneDragCorner(drag, releasePlanPoint);
  if (!raw || !drag || !fin(drag?.corner?.x) || !fin(drag?.corner?.z)) return null;
  if (raw.x === drag.corner.x && raw.z === drag.corner.z) return null;
  const roundX = Math.round(raw.x);
  const roundZ = Math.round(raw.z);
  if (roundX === drag.corner.x && roundZ === drag.corner.z) return null;
  return { x_inches: roundX, z_inches: roundZ };
}

// Re-resolve the dragged row at release time — the canvas's
// findCurrentIndex + fingerprint guard as one pure step. 'index' identity
// (id-less legacy rows) cancels when the array length changed; component/
// legacy ids re-find their row. A fingerprint mismatch (authoritative write
// mid-gesture) cancels. Returns { index, item } or null.
export function resolveSceneDragTarget(drag, items, { keyOf = layoutItemKey, fingerprintOf = layoutItemFingerprint } = {}) {
  if (!drag || !Array.isArray(items)) return null;
  let index;
  if (drag.identityKind === "index") {
    index = items.length === drag.count ? drag.legacyIndex : -1;
  } else {
    index = items.findIndex((it, i) => keyOf(it, i) === drag.key);
  }
  if (typeof index !== "number" || index < 0 || index >= items.length) return null;
  const item = items[index];
  if (fingerprintOf(item) !== drag.fingerprint) return null;
  return { index, item };
}

// ---------------------------------------------------------------------------
// Keyboard manipulation + numeric fallback
// ---------------------------------------------------------------------------

export const SCENE_KEYBOARD_STEP_INCHES = 1;
export const SCENE_KEYBOARD_BIG_STEP_INCHES = 12;

// Arrow-key nudge delta, or null. Mirrors the canvas: ctrl/meta/alt bail
// (browser shortcuts pass through), Shift multiplies the step to 12",
// non-arrow keys return null. preventDefault stays a caller concern (the
// canvas only prevents after the row validates).
export function keyboardNudge(event, { step = SCENE_KEYBOARD_STEP_INCHES, bigStep = SCENE_KEYBOARD_BIG_STEP_INCHES } = {}) {
  if (!event || typeof event !== "object") return null;
  if (event.ctrlKey || event.metaKey || event.altKey) return null;
  const s = event.shiftKey ? bigStep : step;
  const dirs = { ArrowLeft: [-s, 0], ArrowRight: [s, 0], ArrowUp: [0, -s], ArrowDown: [0, s] };
  const d = dirs[event.key];
  if (!d) return null;
  return { dx: d[0], dz: d[1] };
}

// Apply a delta to a position — keyboard nudges and typed-coordinate bumps
// produce the same { x_inches, z_inches } patch shape onMoveItem consumes.
// No rounding: authored fractional corners stay fractional (canvas parity).
export function nudgePatch(position, delta) {
  const pos = planPointOf(position);
  if (!pos || !delta || !fin(delta.dx) || !fin(delta.dz)) return null;
  return { x_inches: pos.x + delta.dx, z_inches: pos.z + delta.dz };
}

// Typed-coordinate entry — the numeric fallback path. Accepts { x, z } or
// { x_inches, z_inches }; finite-only, no clamping (bounds decisions belong
// to the editor, not the primitive). `round` opts into whole-inch commits.
export function positionPatch(point, { round = false } = {}) {
  const p = planPointOf(point);
  if (!p) return null;
  const x = round ? Math.round(p.x) : p.x;
  const z = round ? Math.round(p.z) : p.z;
  if (!fin(x) || !fin(z)) return null;
  return { x_inches: x, z_inches: z };
}

// ---------------------------------------------------------------------------
// Snapping
// ---------------------------------------------------------------------------

// Snap one value to a step. Non-finite values/steps pass through unchanged —
// snapping never invents or destroys authored data.
export function snapValue(v, step) {
  if (!fin(v) || !fin(step) || step <= 0) return v;
  return Math.round(v / step) * step;
}

// Snap a plan point to a uniform grid. Returns { x, z } or null on invalid
// input; `step` is inches (e.g. 1 for the default grid, 12 for foot marks).
export function snapPlanPoint(point, step) {
  const p = planPointOf(point);
  if (!p || !fin(step) || step <= 0) return null;
  return { x: snapValue(p.x, step), z: snapValue(p.z, step) };
}

// Alignment-snap candidates for a scene: every x and z "interesting"
// coordinate a dragged corner could align to — item edges + centers, pole
// points, wall vertices, and the plan bounds. `excludeKey` drops the row
// being dragged so it cannot snap to itself. Deterministic: candidates are
// deduped and returned in stable sorted order with their source.
export function snapCandidatesForScene(scene, { excludeKey, includeBounds = true, includeCenters = true, extent = PLAN_EXTENT } = {}) {
  const xMap = new Map();
  const zMap = new Map();
  const add = (axis, value, source) => {
    if (!fin(value)) return;
    const map = axis === "x" ? xMap : zMap;
    if (!map.has(value)) map.set(value, source);
  };
  if (includeBounds) {
    const w = fin(extent?.width) ? extent.width : DEFAULT_PLAN_EXTENT.width;
    const d = fin(extent?.depth) ? extent.depth : DEFAULT_PLAN_EXTENT.depth;
    add("x", 0, { kind: "bound" });
    add("x", w, { kind: "bound" });
    add("z", 0, { kind: "bound" });
    add("z", d, { kind: "bound" });
  }
  (scene?.items || []).forEach((item, i) => {
    const key = layoutItemKey(item, i);
    if (excludeKey && key === excludeKey) return;
    const g = itemPlanGeometry(item);
    if (!g) return;
    add("x", g.corner.x, { kind: "item-edge", index: i, key });
    add("x", g.corner.x + g.size.width, { kind: "item-edge", index: i, key });
    add("z", g.corner.z, { kind: "item-edge", index: i, key });
    add("z", g.corner.z + g.size.depth, { kind: "item-edge", index: i, key });
    if (includeCenters) {
      add("x", g.center.x, { kind: "item-center", index: i, key });
      add("z", g.center.z, { kind: "item-center", index: i, key });
    }
  });
  (scene?.poles || []).forEach((pole, i) => {
    const key = layoutItemKey(pole, i);
    if (excludeKey && key === excludeKey) return;
    const q = planPointOf({ x: pole?.x_inches, z: pole?.z_inches });
    if (!q) return;
    add("x", q.x, { kind: "pole", index: i, key });
    add("z", q.z, { kind: "pole", index: i, key });
  });
  (scene?.walls || []).forEach((wall, i) => {
    const key = layoutItemKey(wall, i);
    if (excludeKey && key === excludeKey) return;
    const g = wallPlanGeometry(wall);
    if (!g) return;
    g.points.forEach((q, j) => {
      add("x", q.x, { kind: "wall-vertex", index: i, key, vertexIndex: g.indices[j] });
      add("z", q.z, { kind: "wall-vertex", index: i, key, vertexIndex: g.indices[j] });
    });
  });
  const sort = (map) => [...map.entries()].map(([value, source]) => ({ value, source })).sort((a, b) => a.value - b.value);
  return { x: sort(xMap), z: sort(zMap) };
}

// Snap a plan point to candidate axes. Nearest candidate within `tolInches`
// wins per axis; ties resolve to the smaller value then first source.
// Returns { x, z, guides } — guides lists the winning source per snapped
// axis for alignment-line rendering (O-035).
export function snapToCandidates(point, candidates, tolInches) {
  const p = planPointOf(point);
  if (!p || !candidates || !fin(tolInches) || tolInches < 0) return null;
  const pick = (axis, v) => {
    let best = null;
    for (const c of candidates[axis] || []) {
      const delta = Math.abs(c.value - v);
      if (delta > tolInches) continue;
      if (!best || delta < best.delta || (delta === best.delta && c.value < best.value)) {
        best = { value: c.value, source: c.source, delta };
      }
    }
    return best;
  };
  const gx = pick("x", p.x);
  const gz = pick("z", p.z);
  const guides = [];
  if (gx) guides.push({ axis: "x", value: gx.value, source: gx.source, delta: gx.delta });
  if (gz) guides.push({ axis: "z", value: gz.value, source: gz.source, delta: gz.delta });
  return { x: gx ? gx.value : p.x, z: gz ? gz.value : p.z, guides };
}

// ---------------------------------------------------------------------------
// Scene-edit records (O-040 — the stroke-undo seam)
// ---------------------------------------------------------------------------
//
// A finished gesture or keyboard edit as a history-ready record: `before`
// holds the pre-stroke state, `after` the committed patch — for item moves
// both are { x_inches, z_inches } patch-shaped, so the record doubles as
// the undo payload. Anchors are the history store's concern (consumers
// stamp before/after anchors at record time); identity (`key`,
// `identityKind`) rides along for target resolution + labels.

export const SCENE_EDIT_ITEM_MOVE = "item-move";

// A committed corner drag. `drag` is the live beginSceneDrag record (its
// `corner` is the captured pre-stroke state); `patch` is the commitSceneDrag
// result. Null on any missing/invalid piece — callers already null-check
// patch/target upstream.
export function sceneEditFromDrag(drag, patch) {
  if (!drag || !patch) return null;
  if (!fin(drag?.corner?.x) || !fin(drag?.corner?.z)) return null;
  if (!fin(patch?.x_inches) || !fin(patch?.z_inches)) return null;
  return {
    kind: SCENE_EDIT_ITEM_MOVE,
    method: "drag",
    key: drag.key ?? null,
    identityKind: drag.identityKind ?? null,
    before: { x_inches: drag.corner.x, z_inches: drag.corner.z },
    after: { x_inches: patch.x_inches, z_inches: patch.z_inches },
  };
}

// A keyboard nudge — same before/after shape as the drag path so the
// history store treats every item move uniformly. `position` is the row's
// current authored position ({x,z} or {x_inches,z_inches}); `key` is the
// layoutItemKey identity the consumer resolves targets + bursts by.
export function sceneEditFromNudge(key, position, patch) {
  const pos = planPointOf(position);
  if (!pos || !patch || !fin(patch?.x_inches) || !fin(patch?.z_inches)) return null;
  return {
    kind: SCENE_EDIT_ITEM_MOVE,
    method: "nudge",
    key: key ?? null,
    identityKind: "key",
    before: { x_inches: pos.x, z_inches: pos.z },
    after: { x_inches: patch.x_inches, z_inches: patch.z_inches },
  };
}

// Burst-coalescing identity (O-040 "sensible history"): drags never merge —
// one gesture is already one commit. Nudges on the same row merge while the
// key stream keeps hitting the same target; the merge window lives in the
// history store, this is only the identity. Anything else returns null and
// records as its own command.
export function sceneEditCoalesceKey(edit) {
  if (!edit || edit.method !== "nudge" || typeof edit.key !== "string" || !edit.key) return null;
  return `nudge:${edit.key}`;
}

// O-034 (CMP-C03) — foundation scene tree + selection model.
//
// Pure, deterministic, DOM-free scene-object addressing and selection state.
// One implementation answers every selection question the estimator asks:
// "what node is under this point" (hitTestPlanAll topmost wins — the canvas
// paint order), "what objects does this rubber-band rect cover" (plan-space
// region test), "what did this row resolve to" (all five assembly arrays +
// wall segments + pole signs), "what is selected" (ordered ids + primary +
// hit-part detail), "what is its breadcrumb" (parent chain through mounts),
// "is this gesture a click or a drag" (screen-px slop threshold), and "what
// survived this scene change" (identity reconciliation that never lets a
// stale selection address a different row).
//
// Consumed by the layout canvas at its existing pointer seam; consumed next
// by the object-tree/properties/highlight panels (deferred page wiring —
// the store is subscribe()/stateVersion-ready for useSyncExternalStore, the
// same mount shape as foundationSceneHistory).
//
// Geometry contract (owned by foundationLayoutModel.js /
// foundationAssemblyModel.js / foundationSceneInput.js — imported
// read-only):
//   * items carry a TOP-LEFT plan corner + unrotated footprint + rotation
//     about the footprint center; pillars are circles (diameter x diameter).
//   * poles carry a plan POINT.
//   * walls carry shape.points [{x,z}] + shape.closed; geometric segment i
//     runs points[i] -> points[(i+1) % n] (last wraps only when closed);
//     shape.segments[i] is the authored row for geometric segment i.
//   * wall_caps / signage_cabinets / pole signs carry NO plan coordinates —
//     they are reachable through the tree and the pointer (mounted parents)
//     but never hit-tested or region-selected.
//
// Node-id contract: `${kind}:${identity}` strings, deterministic functions
// of the scene — rebuild the scene and the same object gets the same id.
//   item / pole / wall / wall-cap / cabinet → `${kind}:${layoutItemKey}`
//   wall-segment → `wall-segment:${wallKey}|${segRef}`   segRef =
//     `component:${segment_component_id}` when the authored segment row
//     carries one, else `index:${segmentIndex}` (geometric position).
//   pole-sign → `pole-sign:${poleKey}|${signRef}` same ref rule.
// `|` is the sub-object delimiter; ids split on the LAST `|` so a parent
// key may itself contain `|` safely (only a component_id containing `|`
// inside the trailing ref could confuse a parse — malformed authored ids
// degrade, never crash; resolution is byId-driven, not parse-driven).
//
// Click-vs-drag contract: gestures resolve at RELEASE displacement, not
// intermediate travel — a press that returns within
// SELECTION_CLICK_THRESHOLD_PX of its down point is a click (selection
// applies); anything beyond it is a drag (selection untouched). This is the
// "drags don't deselect" rule: the canvas's own 1-inch commit wiggle guard
// is unrelated — this slop is measured in screen px on the pointer.
//
// Keyboard contract (selectionKeyAction / store.applyKey):
//   Tab / ArrowRight / ArrowDown → cycle forward through tree order;
//   Shift+Tab / ArrowLeft / ArrowUp → cycle backward;
//   Escape → clear; Delete/Backspace → 'delete-request' — the store NEVER
//   deletes; the action is a hook point the consumer's commit path serves.
//   ctrl/meta/alt modifiers bail (browser shortcuts pass through), except
//   Shift which is the additive/cycle-reverse modifier. On item elements
//   the canvas runs its nudge path FIRST, so arrows there stay nudges —
//   cycle only reaches arrows on the plan container.
//
// Reconcile contract: an exact-id match keeps the selection (positional
// `index:` ids auto-track the row now at that position — the same identity
// rule resolveSceneDragTarget uses: a positional id that vanished means the
// collection shrank and the selection is dropped, never re-pointed).
// Component/legacy ids survive reorders; `index:` segment/sign refs upgrade
// to `component:` ids when normalization mints them (reported in remapped).
// Part detail re-validates: an out-of-range vertexIndex/segmentIndex
// downgrades to {type:'row'} — the object stays selected, the stale
// sub-part claim is dropped.

import {
  layoutItemKey,
} from "./foundationLayoutModel";
import {
  planPointOf,
  framePlanCorners,
} from "./foundationSceneTransforms";
import {
  itemPlanGeometry,
  wallPlanGeometry,
  hitTestPlanAll,
  hitLabel,
  sceneObjectLabel,
} from "./foundationSceneInput";

const fin = (v) => typeof v === "number" && Number.isFinite(v);
const isId = (v) => typeof v === "string" && v.length > 0;
const hypot = Math.hypot;

// Pointer travel below this is a click, not a drag (css-px on the pointer —
// matches the slop browsers apply before a press becomes a move).
export const SELECTION_CLICK_THRESHOLD_PX = 5;

// Region-select modes: 'intersect' = the rubber band touches the object
// (default, rubber-band convention); 'contain' = the object must lie fully
// inside the region (deliberate selection).
export const REGION_SELECT_MODES = Object.freeze(["intersect", "contain"]);

export const SCENE_NODE_KINDS = Object.freeze([
  "item", "wall", "wall-segment", "pole", "pole-sign", "wall-cap", "cabinet",
]);

const COLLECTION_OF_KIND = Object.freeze({
  item: "items",
  wall: "walls",
  "wall-segment": "walls",
  pole: "poles",
  "pole-sign": "poles",
  "wall-cap": "wall_caps",
  cabinet: "signage_cabinets",
});

// ---------------------------------------------------------------------------
// Scene normalization — accepts the assembly's snake_case arrays or the
// canvas's camelCase props interchangeably.
// ---------------------------------------------------------------------------

export function sceneCollections(scene) {
  const s = scene && typeof scene === "object" ? scene : {};
  return {
    items: Array.isArray(s.items) ? s.items : [],
    walls: Array.isArray(s.walls) ? s.walls : [],
    poles: Array.isArray(s.poles) ? s.poles : [],
    wall_caps: Array.isArray(s.wall_caps) ? s.wall_caps : Array.isArray(s.wallCaps) ? s.wallCaps : [],
    signage_cabinets: Array.isArray(s.signage_cabinets)
      ? s.signage_cabinets
      : Array.isArray(s.signageCabinets) ? s.signageCabinets : [],
  };
}

// ---------------------------------------------------------------------------
// Node ids + the object tree
// ---------------------------------------------------------------------------

const subRef = (componentId, index) =>
  isId(componentId) ? `component:${componentId}` : `index:${index}`;

export const sceneNodeId = Object.freeze({
  item: (key) => `item:${key}`,
  pole: (key) => `pole:${key}`,
  wall: (key) => `wall:${key}`,
  wallSegment: (wallKey, ref) => `wall-segment:${wallKey}|${ref}`,
  poleSign: (poleKey, ref) => `pole-sign:${poleKey}|${ref}`,
  wallCap: (key) => `wall-cap:${key}`,
  cabinet: (key) => `cabinet:${key}`,
});

// Parse a node id into { kind, key, parentKey, ref }. Longest prefixes
// first; sub-object ids split on the LAST '|'. Unknown shapes return null —
// callers treat unparseable ids as foreign and leave them alone.
export function parseSceneNodeId(id) {
  if (typeof id !== "string" || !id) return null;
  const prefixed = (prefix, kind, sub) => {
    if (!id.startsWith(prefix)) return null;
    const body = id.slice(prefix.length);
    if (!sub) return { kind, key: body, parentKey: null, ref: null };
    const cut = body.lastIndexOf("|");
    if (cut < 0) return { kind, key: body, parentKey: null, ref: null };
    return { kind, key: body.slice(0, cut), parentKey: body.slice(0, cut), ref: body.slice(cut + 1) };
  };
  return (
    prefixed("wall-segment:", "wall-segment", true) ||
    prefixed("pole-sign:", "pole-sign", true) ||
    prefixed("wall-cap:", "wall-cap") ||
    prefixed("item:", "item") ||
    prefixed("wall:", "wall") ||
    prefixed("pole:", "pole") ||
    prefixed("cabinet:", "cabinet") ||
    null
  );
}

// Geometric segment count for a wall — points.length with closed wrap.
const wallSegmentCount = (wall) => {
  const g = wallPlanGeometry(wall);
  if (!g || g.points.length < 2) return 0;
  return g.closed ? g.points.length : g.points.length - 1;
};

const isRecord = (v) => !!v && typeof v === "object" && !Array.isArray(v);
const segRow = (wall, i) => (Array.isArray(wall?.shape?.segments) ? wall.shape.segments[i] : undefined);

// Parent component-id resolution. Only a live component_id link counts —
// reserved "unresolved:" tokens and dangling refs resolve to null, matching
// the assembly model's parent semantics (a dangling parent is shown as
// unresolved, not silently re-pointed).
const parentItemId = (ref, rows, kind) => {
  if (!isId(ref) || ref.startsWith("unresolved:")) return null;
  const i = (rows || []).findIndex((r) => r?.component_id === ref);
  return i >= 0 ? `${kind}:${layoutItemKey(rows[i], i)}` : null;
};

// Legacy-index parent fallback — pre-normalize scenes may only carry the
// *_idx/*_index mirrors. Used ONLY when no component ref is present at all
// (a dangling component ref stays unresolved; the index mirror is not
// consulted for it — the assembly model treats them as the same link).
const parentByIndex = (idx, rows, kind) => {
  const n = typeof idx === "string" && /^\d+$/.test(idx) ? parseInt(idx, 10) : idx;
  if (!Number.isInteger(n) || n < 0 || n >= (rows || []).length) return null;
  return `${kind}:${layoutItemKey(rows[n], n)}`;
};

// A ref that is PRESENT (even "" or an "unresolved:" token) means the link
// was authored — the index mirror is only a migration path when no
// component ref exists at all.
const refPresent = (v) => v !== undefined && v !== null;

const parentForPole = (p, cols) => {
  if (refPresent(p?.foundation_component_id)) return parentItemId(p.foundation_component_id, cols.items, "item");
  return parentByIndex(p?.foundation_idx ?? p?.foundation_index, cols.items, "item");
};
const parentForCabinet = (c, cols) => {
  if (c?.mount === "pole") {
    if (refPresent(c?.pole_component_id)) return parentItemId(c.pole_component_id, cols.poles, "pole");
    return parentByIndex(c?.pole_index ?? c?.pole_idx, cols.poles, "pole");
  }
  if (c?.mount === "foundation") {
    if (refPresent(c?.foundation_component_id)) return parentItemId(c.foundation_component_id, cols.items, "item");
    return parentByIndex(c?.foundation_index ?? c?.foundation_idx, cols.items, "item");
  }
  return null;
};

// The object tree — one deterministic pass over all five assembly arrays
// plus wall segments and pole signs. Returns { nodes: Map, order: [ids]
// (DFS, parent before children), roots: [ids] }. Nodes are snapshots:
// { id, kind, collection, index, key, componentId, label, parentId,
//   childIds, depth, planar, selectable, segmentIndex?, vertex?... }.
export function buildSceneTree(scene) {
  const cols = sceneCollections(scene);
  const nodes = new Map();
  const childIds = new Map();
  const addChild = (parentId, id) => {
    if (!parentId) return;
    const list = childIds.get(parentId) || [];
    list.push(id);
    childIds.set(parentId, list);
  };

  const define = (node) => {
    if (!node || !isId(node.id) || nodes.has(node.id)) return null;
    nodes.set(node.id, { childIds: [], ...node });
    addChild(node.parentId, node.id);
    return node.id;
  };

  // Parents first — mounted rows need their parents to already exist.
  const itemIds = cols.items.map((it, i) => define({
    id: sceneNodeId.item(layoutItemKey(it, i)),
    kind: "item", collection: "items", index: i,
    key: layoutItemKey(it, i), componentId: it?.component_id ?? null,
    label: sceneObjectLabel("items", i),
    parentId: null, depth: 0, planar: true, selectable: true,
  }));

  const wallIds = cols.walls.map((w, i) => define({
    id: sceneNodeId.wall(layoutItemKey(w, i)),
    kind: "wall", collection: "walls", index: i,
    key: layoutItemKey(w, i), componentId: w?.component_id ?? null,
    label: sceneObjectLabel("walls", i),
    parentId: null, depth: 0, planar: true, selectable: true,
  }));

  const poleIds = cols.poles.map((p, i) => {
    const parent = parentForPole(p, cols);
    return define({
      id: sceneNodeId.pole(layoutItemKey(p, i)),
      kind: "pole", collection: "poles", index: i,
      key: layoutItemKey(p, i), componentId: p?.component_id ?? null,
      label: sceneObjectLabel("poles", i),
      parentId: parent, planar: true, selectable: true,
      parentComponentId: isId(p?.foundation_component_id) ? p.foundation_component_id : null,
    });
  });

  // Children: wall segments (one node per GEOMETRIC segment — a wall with
  // no authored shape.segments still exposes its segments to selection;
  // the row's component_id rides when the authored row exists).
  cols.walls.forEach((w, i) => {
    const wallKey = layoutItemKey(w, i);
    const segs = Array.isArray(w?.shape?.segments) ? w.shape.segments : [];
    const count = Math.max(wallSegmentCount(w), segs.length);
    for (let s = 0; s < count; s += 1) {
      const ref = subRef(segs[s]?.component_id, s);
      define({
        id: sceneNodeId.wallSegment(wallKey, ref),
        kind: "wall-segment", collection: "walls", index: i,
        key: wallKey, componentId: segs[s]?.component_id ?? null,
        label: `Segment ${s + 1}`,
        parentId: wallIds[i], planar: true, selectable: true,
        segmentIndex: s, segmentComponentId: segs[s]?.component_id ?? null,
      });
    }
  });

  // Children: pole signs.
  cols.poles.forEach((p, i) => {
    const poleKey = layoutItemKey(p, i);
    const signs = Array.isArray(p?.signs) ? p.signs : [];
    signs.forEach((s, j) => {
      const ref = subRef(s?.component_id, j);
      define({
        id: sceneNodeId.poleSign(poleKey, ref),
        kind: "pole-sign", collection: "poles", index: i,
        key: poleKey, componentId: s?.component_id ?? null,
        label: `Sign ${j + 1}`,
        parentId: poleIds[i], planar: false, selectable: true,
        signIndex: j,
      });
    });
  });

  // Mounted rows: wall caps → segment node when the segment link resolves,
  // else the wall node, else root. Both refs must be live component ids;
  // the segment must belong to the resolved wall (a cross-wall ref dangles).
  cols.wall_caps.forEach((c, i) => {
    const key = layoutItemKey(c, i);
    const wallNodeId = refPresent(c?.wall_component_id)
      ? parentItemId(c.wall_component_id, cols.walls, "wall")
      : parentByIndex(c?.wall_index, cols.walls, "wall");
    let parentId = null;
    if (wallNodeId) {
      parentId = wallNodeId;
      if (isId(c?.segment_component_id) && !c.segment_component_id.startsWith("unresolved:")) {
        const wi = nodes.get(wallNodeId)?.index;
        const segs = wi !== undefined ? cols.walls[wi]?.shape?.segments : null;
        const si = Array.isArray(segs)
          ? segs.findIndex((s) => s?.component_id === c.segment_component_id)
          : -1;
        if (si >= 0) parentId = sceneNodeId.wallSegment(layoutItemKey(cols.walls[wi], wi), `component:${c.segment_component_id}`);
      }
    }
    define({
      id: sceneNodeId.wallCap(key),
      kind: "wall-cap", collection: "wall_caps", index: i,
      key, componentId: c?.component_id ?? null,
      label: `Cap ${i + 1}`,
      parentId, planar: false, selectable: true,
      parentComponentId: isId(c?.wall_component_id) ? c.wall_component_id : null,
    });
  });

  // Mounted rows: cabinets → pole node (mount 'pole') or item node
  // ('foundation'); unknown/absent mounts sit at root, same as the issues
  // list treats them (priced + visible until reassigned).
  cols.signage_cabinets.forEach((c, i) => {
    const key = layoutItemKey(c, i);
    const parentId = parentForCabinet(c, cols);
    const parentComponentId = c?.mount === "pole"
      ? (isId(c?.pole_component_id) ? c.pole_component_id : null)
      : c?.mount === "foundation"
        ? (isId(c?.foundation_component_id) ? c.foundation_component_id : null)
        : null;
    define({
      id: sceneNodeId.cabinet(key),
      kind: "cabinet", collection: "signage_cabinets", index: i,
      key, componentId: c?.component_id ?? null,
      label: `Cabinet ${i + 1}`,
      parentId, planar: false, selectable: true,
      parentComponentId,
    });
  });

  // DFS order: roots in collection order (items, walls, poles, caps,
  // cabinets — unmounted rows stay roots), children nested after parents.
  const order = [];
  const roots = [];
  const depth = new Map();
  const visit = (id, d) => {
    depth.set(id, d);
    const n = nodes.get(id);
    if (n) n.depth = d;
    order.push(id);
    (childIds.get(id) || []).forEach((c) => visit(c, d + 1));
  };
  for (const id of itemIds) if (id) visit(id, 0);
  for (const id of wallIds) if (id) visit(id, 0);
  for (const id of poleIds) if (id && !nodes.get(id)?.parentId) visit(id, 0);
  // poles with parents are visited inside their item's subtree already —
  // any missed (defensive) nodes append in creation order.
  for (const id of nodes.keys()) if (!depth.has(id)) visit(id, 0);
  for (const [id, n] of nodes) if (!n.parentId) roots.push(id);

  return { nodes, order, roots };
};

// Resolve a node id to its live row(s). Returns { node, row, collection,
// index, wallIndex?, segmentIndex?, signIndex? } or null when the id no
// longer addresses anything. Parse-driven (no tree build needed).
export function resolveSceneNode(scene, nodeId) {
  const parsed = parseSceneNodeId(nodeId);
  if (!parsed) return null;
  const cols = sceneCollections(scene);
  const findRow = (rows, key) => {
    const i = (rows || []).findIndex((r, j) => layoutItemKey(r, j) === key);
    return i >= 0 ? { row: rows[i], index: i } : null;
  };
  switch (parsed.kind) {
    case "item":
    case "pole":
    case "wall":
    case "wall-cap":
    case "cabinet": {
      const found = findRow(cols[COLLECTION_OF_KIND[parsed.kind]], parsed.key);
      if (!found) return null;
      return {
        node: parsed.kind, collection: COLLECTION_OF_KIND[parsed.kind],
        index: found.index, row: found.row, id: nodeId,
      };
    }
    case "wall-segment": {
      const found = findRow(cols.walls, parsed.key);
      if (!found) return null;
      const segs = Array.isArray(found.row?.shape?.segments) ? found.row.shape.segments : [];
      let si = -1;
      if (parsed.ref?.startsWith("component:")) {
        si = segs.findIndex((s) => s?.component_id === parsed.ref.slice(10));
      } else if (parsed.ref?.startsWith("index:")) {
        const n = parseInt(parsed.ref.slice(6), 10);
        si = Number.isInteger(n) && n >= 0 && n < Math.max(wallSegmentCount(found.row), segs.length) ? n : -1;
      }
      if (si < 0) return null;
      return {
        node: "wall-segment", collection: "walls",
        index: found.index, row: found.row, wallIndex: found.index,
        segmentIndex: si, segment: segs[si] ?? null, id: nodeId,
      };
    }
    case "pole-sign": {
      const found = findRow(cols.poles, parsed.key);
      if (!found) return null;
      const signs = Array.isArray(found.row?.signs) ? found.row.signs : [];
      let si = -1;
      if (parsed.ref?.startsWith("component:")) {
        si = signs.findIndex((s) => s?.component_id === parsed.ref.slice(10));
      } else if (parsed.ref?.startsWith("index:")) {
        const n = parseInt(parsed.ref.slice(6), 10);
        si = Number.isInteger(n) && n >= 0 && n < signs.length ? n : -1;
      }
      if (si < 0) return null;
      return {
        node: "pole-sign", collection: "poles",
        index: found.index, row: found.row, poleIndex: found.index,
        signIndex: si, sign: signs[si] ?? null, id: nodeId,
      };
    }
    default:
      return null;
  }
}

// Root → node breadcrumb (labels + ids) for the properties panel's parent
// trail: e.g. [Wall 1, Segment 2, Cap 1]. Builds the tree once.
export function nodeBreadcrumb(scene, nodeId) {
  const tree = buildSceneTree(scene);
  const trail = [];
  let cur = tree.nodes.get(nodeId) || null;
  let guard = 0;
  while (cur && guard < 64) {
    trail.unshift({ id: cur.id, kind: cur.kind, label: cur.label, index: cur.index });
    cur = cur.parentId ? tree.nodes.get(cur.parentId) : null;
    guard += 1;
  }
  return trail;
}

// ---------------------------------------------------------------------------
// Hits → nodes (paint-order z-top-wins via hitTestPlanAll order)
// ---------------------------------------------------------------------------

// Sub-part detail carried on a selection entry. Types: 'face' | 'edge' |
// 'vertex' | 'segment' | 'point' | 'row' (whole object — tree/marquee
// selects carry no finer claim).
export function hitPartFromHit(hit) {
  if (!hit || typeof hit !== "object") return { type: "row" };
  switch (hit.kind) {
    case "item-face": return { type: "face" };
    case "item-edge": return { type: "edge", edge: hit.edge ?? null };
    case "item-vertex": return { type: "vertex", corner: hit.corner ?? null };
    case "pole": return { type: "point" };
    case "wall-vertex": return { type: "vertex", vertexIndex: hit.vertexIndex ?? null };
    case "wall-segment":
      return {
        type: "segment",
        segmentIndex: hit.segmentIndex ?? null,
        segmentComponentId: hit.segmentComponentId ?? null,
        t: fin(hit.t) ? hit.t : null,
      };
    case "wall-face": return { type: "face" };
    default: return { type: "row" };
  }
}

// The node a hit selects + its part. Wall-segment hits address the SEGMENT
// node (a real tree child); wall vertex/face hits address the wall with the
// part recorded for future edit surfaces (O-035 handles read it).
export function nodeTargetForHit(hit) {
  if (!hit || typeof hit !== "object" || !isId(hit.collection)) return null;
  const part = hitPartFromHit(hit);
  if (hit.collection === "items") {
    return { id: sceneNodeId.item(hit.key), kind: "item", part, hit };
  }
  if (hit.collection === "poles") {
    return { id: sceneNodeId.pole(hit.key), kind: "pole", part, hit };
  }
  if (hit.collection === "walls") {
    if (hit.kind === "wall-segment" && fin(hit.segmentIndex)) {
      const ref = subRef(hit.segmentComponentId, hit.segmentIndex);
      return {
        id: sceneNodeId.wallSegment(hit.key, ref),
        kind: "wall-segment", part, hit,
      };
    }
    return { id: sceneNodeId.wall(hit.key), kind: "wall", part, hit };
  }
  return null;
}

// Descriptor extras the store snapshots from a live hit — what a properties
// panel renders without re-walking the scene (label uses the input seam's
// hitLabel so sub-part text matches every other surface).
const hitDescriptor = (hit) => ({
  collection: hit?.collection ?? null,
  index: hit?.index ?? null,
  key: hit?.key ?? null,
  componentId: hit?.componentId ?? null,
  label: hit ? hitLabel(hit) : null,
});

// ---------------------------------------------------------------------------
// Click-vs-drag disambiguation (screen-px slop at release)
// ---------------------------------------------------------------------------

// A press that MIGHT become a click. `hit` is the hitTestPlanAll topmost
// result at the down point (null for empty space — the canvas records the
// same record for marquee decisions).
export function beginClickCandidate({ pointerId, clientX, clientY, hit = null, additive = false } = {}) {
  if (!fin(clientX) || !fin(clientY)) return null;
  return {
    pointerId: pointerId === undefined ? null : pointerId,
    clientX, clientY,
    hit,
    additive: additive === true,
  };
}

// Screen-px travel from the recorded down point to a current/release point.
export function clickTravelPx(candidate, point) {
  if (!candidate || !fin(candidate.clientX) || !fin(candidate.clientY)) return null;
  const x = fin(point?.clientX) ? point.clientX : fin(point?.x) ? point.x : null;
  const y = fin(point?.clientY) ? point.clientY : fin(point?.y) ? point.y : null;
  if (x === null || y === null) return null;
  return hypot(x - candidate.clientX, y - candidate.clientY);
}

// True when the gesture resolves as a click: release travelled less than
// the slop threshold from its down point. Anything else — a real drag, or a
// drag that wandered out and wandered back — is not a click.
export function isClickRelease(candidate, releaseEvent, thresholdPx = SELECTION_CLICK_THRESHOLD_PX) {
  const d = clickTravelPx(candidate, releaseEvent);
  const t = fin(thresholdPx) && thresholdPx >= 0 ? thresholdPx : SELECTION_CLICK_THRESHOLD_PX;
  return d !== null && d < t;
}

// ---------------------------------------------------------------------------
// Keyboard (cycle / clear / delete hook)
// ---------------------------------------------------------------------------

// Map a keyboard event to a selection action, or null when the key is not
// the selection layer's business. Modifier rules mirror the input seam's
// keyboardNudge: ctrl/meta/alt bail (browser shortcuts); Shift is allowed
// (it is the additive + cycle-reverse modifier, and Shift+arrows at the
// container level cycle — on items they never reach here: nudge wins).
export function selectionKeyAction(event) {
  if (!event || typeof event !== "object") return null;
  if (event.ctrlKey || event.metaKey || event.altKey) return null;
  const key = event.key;
  if (key === "Tab" || key === "ArrowRight" || key === "ArrowDown") {
    return { action: "cycle", direction: event.shiftKey ? -1 : 1 };
  }
  if (key === "ArrowLeft" || key === "ArrowUp") {
    return { action: "cycle", direction: -1 };
  }
  if (key === "Escape") return { action: "clear" };
  if (key === "Delete" || key === "Backspace") return { action: "delete-request" };
  return null;
}

// ---------------------------------------------------------------------------
// Region (marquee / rubber-band) geometry — plan inches
// ---------------------------------------------------------------------------

// Normalize two plan points into an axis-aligned region.
export function regionFromPoints(a, b) {
  const pa = planPointOf(a);
  const pb = planPointOf(b);
  if (!pa || !pb) return null;
  return {
    minX: Math.min(pa.x, pb.x),
    minZ: Math.min(pa.z, pb.z),
    maxX: Math.max(pa.x, pb.x),
    maxZ: Math.max(pa.z, pb.z),
  };
}

const regionIsUsable = (r) =>
  !!r && fin(r.minX) && fin(r.minZ) && fin(r.maxX) && fin(r.maxZ) && r.minX <= r.maxX && r.minZ <= r.maxZ;

const pointInRegion = (r, p) =>
  p.x >= r.minX && p.x <= r.maxX && p.z >= r.minZ && p.z <= r.maxZ;

const regionCorners = (r) => [
  { x: r.minX, z: r.minZ }, { x: r.maxX, z: r.minZ },
  { x: r.maxX, z: r.maxZ }, { x: r.minX, z: r.maxZ },
];

// Segment-segment intersection, endpoints touching counts (a rubber band
// grazing an edge intersects it — rubber-band convention).
const segSegIntersect = (a, b, c, d) => {
  const cross = (o, p, q) => (p.x - o.x) * (q.z - o.z) - (p.z - o.z) * (q.x - o.x);
  const d1 = cross(c, d, a);
  const d2 = cross(c, d, b);
  const d3 = cross(a, b, c);
  const d4 = cross(a, b, d);
  if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return true;
  const on = (p, q, r0) =>
    Math.min(p.x, q.x) <= r0.x && r0.x <= Math.max(p.x, q.x) &&
    Math.min(p.z, q.z) <= r0.z && r0.z <= Math.max(p.z, q.z) &&
    Math.abs(cross(p, q, r0)) <= 1e-9;
  if (d1 === 0 && on(c, d, a)) return true;
  if (d2 === 0 && on(c, d, b)) return true;
  if (d3 === 0 && on(a, b, c)) return true;
  if (d4 === 0 && on(a, b, d)) return true;
  return false;
};

const segmentIntersectsRegion = (a, b, r) => {
  if (pointInRegion(r, a) || pointInRegion(r, b)) return true;
  const c = regionCorners(r);
  for (let i = 0; i < 4; i += 1) {
    if (segSegIntersect(a, b, c[i], c[(i + 1) % 4])) return true;
  }
  return false;
};

// Rect-rect intersection via the separating-axis test. `cornersA`/`cornersB`
// are the two rects' corner lists [{x,z} x4] — the item's may be rotated,
// the region's are axis-aligned. Exact (both are convex).
const rectsIntersect = (cornersA, cornersB) => {
  const axes = [];
  for (const corners of [cornersA, cornersB]) {
    for (let i = 0; i < 2; i += 1) {
      const e = { x: corners[(i + 1) % 4].x - corners[i].x, z: corners[(i + 1) % 4].z - corners[i].z };
      const len = hypot(e.x, e.z) || 1;
      axes.push({ x: -e.z / len, z: e.x / len }); // unit normal
    }
  }
  for (const axis of axes) {
    const proj = (c) => c.x * axis.x + c.z * axis.z;
    let aMin = Infinity, aMax = -Infinity, bMin = Infinity, bMax = -Infinity;
    for (const c of cornersA) { const p = proj(c); if (p < aMin) aMin = p; if (p > aMax) aMax = p; }
    for (const c of cornersB) { const p = proj(c); if (p < bMin) bMin = p; if (p > bMax) bMax = p; }
    if (aMax < bMin || bMax < aMin) return false;
  }
  return true;
};

const circleIntersectsRegion = (center, radius, r) => {
  const cx = Math.min(Math.max(center.x, r.minX), r.maxX);
  const cz = Math.min(Math.max(center.z, r.minZ), r.maxZ);
  return hypot(center.x - cx, center.z - cz) <= radius;
};

// Even-odd point-in-polygon over finite plan points — same rule the input
// module's hit test applies (kept local: the region test consumes already-
// extracted vertices, and a zero-area/collinear outline honestly reports
// no interior).
const pointInPolygon = (p, pts) => {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i, i += 1) {
    const a = pts[i];
    const b = pts[j];
    if ((a.z > p.z) !== (b.z > p.z) &&
      p.x < ((b.x - a.x) * (p.z - a.z)) / (b.z - a.z) + a.x) {
      inside = !inside;
    }
  }
  return inside;
};

const itemInRegion = (item, r, mode) => {
  const g = itemPlanGeometry(item);
  if (!g) return false;
  if (g.circular) {
    const radius = Math.min(g.size.width, g.size.depth) / 2;
    if (mode === "contain") {
      return (
        g.center.x - radius >= r.minX && g.center.x + radius <= r.maxX &&
        g.center.z - radius >= r.minZ && g.center.z + radius <= r.maxZ
      );
    }
    return circleIntersectsRegion(g.center, radius, r);
  }
  const corners = framePlanCorners(g.frame, g.size);
  if (!corners) return false;
  const list = [corners.nw, corners.ne, corners.se, corners.sw];
  if (mode === "contain") return list.every((c) => pointInRegion(r, c));
  return rectsIntersect(list, regionCorners(r));
};

const wallInRegion = (wall, r, mode) => {
  const g = wallPlanGeometry(wall);
  if (!g || !g.points.length) return false;
  if (mode === "contain") {
    // Region is convex: every vertex inside ⟺ the whole outline inside.
    return g.points.every((p) => pointInRegion(r, p));
  }
  if (g.points.some((p) => pointInRegion(r, p))) return true;
  const segCount = g.closed ? g.points.length : g.points.length - 1;
  for (let i = 0; i < segCount; i += 1) {
    if (segmentIntersectsRegion(g.points[i], g.points[(i + 1) % g.points.length], r)) return true;
  }
  // Region wholly inside a closed outline — the wall surrounds the band.
  if (g.closed && pointInPolygon(regionCorners(r)[0], g.points)) return true;
  return false;
};

// Node ids of planar objects covered by a plan-space region, in tree DFS
// order. Only top-level planar objects qualify — items, poles, walls.
// Wall segments/pole signs are sub-object precision (click-only); caps and
// cabinets carry no plan geometry and are never region-selected.
export function sceneObjectsInRegion(scene, region, { mode = "intersect" } = {}) {
  if (!regionIsUsable(region)) return [];
  const m = REGION_SELECT_MODES.includes(mode) ? mode : "intersect";
  const cols = sceneCollections(scene);
  const picked = new Set();
  cols.items.forEach((it, i) => {
    if (itemInRegion(it, region, m)) picked.add(sceneNodeId.item(layoutItemKey(it, i)));
  });
  cols.walls.forEach((w, i) => {
    if (wallInRegion(w, region, m)) picked.add(sceneNodeId.wall(layoutItemKey(w, i)));
  });
  cols.poles.forEach((p, i) => {
    const q = planPointOf({ x: p?.x_inches, z: p?.z_inches });
    if (q && pointInRegion(region, q)) picked.add(sceneNodeId.pole(layoutItemKey(p, i)));
  });
  // Emit in tree order — the object tree's DFS sequence is the scene's
  // canonical ordering everywhere (cycle, marquee, tree panel).
  const tree = buildSceneTree(scene);
  return tree.order.filter((id) => picked.has(id));
}

// ---------------------------------------------------------------------------
// The selection store
// ---------------------------------------------------------------------------

// A subscribe()/stateVersion-ready store — the same mount shape as
// createSceneHistory (useSyncExternalStore at the page; the canvas keeps an
// internal one when unmounted). The store holds ONLY selection state —
// ordered ids, the primary (active) node, per-id part detail, and the
// transient marquee. The scene is passed per call; nothing here mutates it.
export function createSceneSelection() {
  let ids = [];
  let primaryId = null;
  let parts = {};
  let descriptors = {};
  let marquee = null;
  let version = 0;
  const listeners = new Set();

  const emit = () => {
    version += 1;
    for (const fn of [...listeners]) {
      try { fn(); } catch { /* listener faults never break the store */ }
    }
  };

  const has = (id) => ids.includes(id);
  const descriptorFor = (target, extra = {}) => ({
    id: target.id,
    kind: target.kind ?? parseSceneNodeId(target.id)?.kind ?? null,
    collection: extra.collection ?? null,
    index: extra.index ?? null,
    key: extra.key ?? null,
    componentId: extra.componentId ?? null,
    label: extra.label ?? null,
    parentId: extra.parentId ?? null,
    segmentIndex: extra.segmentIndex ?? null,
    signIndex: extra.signIndex ?? null,
  });

  // Keep a descriptor snapshot; prefer fresh info when given. `target` may
  // be a bare id string — normalize so descriptorFor always sees an object.
  const describe = (id, target, extra) => {
    const t = typeof target === "string" ? { id: target } : target;
    if (!t) return;
    descriptors = { ...descriptors, [id]: descriptorFor(t, extra) };
  };

  const setState = (nextIds, nextPrimary, nextParts, nextDescriptors) => {
    ids = nextIds;
    primaryId = nextPrimary;
    parts = nextParts;
    descriptors = nextDescriptors;
    emit();
  };

  const setSelection = (entries, { primary } = {}) => {
    const list = Array.isArray(entries) ? entries : [];
    const seen = new Set();
    const nextIds = [];
    const nextParts = {};
    const nextDescriptors = {};
    for (const entry of list) {
      const id = typeof entry === "string" ? entry : entry?.id;
      if (!isId(id) || seen.has(id)) continue;
      seen.add(id);
      nextIds.push(id);
      nextParts[id] = typeof entry === "object" && entry?.part ? entry.part : { type: "row" };
      nextDescriptors[id] = typeof entry === "object" && entry?.descriptor
        ? entry.descriptor
        : { id, kind: parseSceneNodeId(id)?.kind ?? null, collection: null, index: null, key: null, componentId: null, label: null, parentId: null, segmentIndex: null, signIndex: null };
    }
    const nextPrimary = isId(primary) && seen.has(primary)
      ? primary
      : nextIds[nextIds.length - 1] ?? null;
    setState(nextIds, nextPrimary, nextParts, nextDescriptors);
    return { status: "set", ids: [...nextIds], primaryId: nextPrimary };
  };

  // Core select. `target` = { id, kind?, part?, descriptor? } or a bare id.
  // plain → replace; additive → toggle membership (ctrl/meta convention;
  // shift+click additive callers pass the same flag — clicking a selected
  // row with an additive modifier removes it and drops primary to the last
  // remaining, the uniform rule).
  const select = (target, { additive = false } = {}) => {
    const id = typeof target === "string" ? target : target?.id;
    if (!isId(id)) {
      // A null/foreign target is an empty-space click: plain clears,
      // additive keeps (nothing was added).
      if (!additive) {
        if (!ids.length && primaryId === null) return { status: "empty" };
        setState([], null, {}, {});
        return { status: "cleared" };
      }
      return { status: "kept", ids: [...ids] };
    }
    if (!additive) {
      const part = typeof target === "object" && target?.part ? target.part : { type: "row" };
      describe(id, target, target?.descriptor);
      setState([id], id, { [id]: part }, descriptors);
      return { status: "selected", id, primaryId: id };
    }
    if (has(id)) {
      const nextIds = ids.filter((x) => x !== id);
      const nextParts = { ...parts }; delete nextParts[id];
      const nextDescriptors = { ...descriptors }; delete nextDescriptors[id];
      const nextPrimary = primaryId === id ? nextIds[nextIds.length - 1] ?? null : primaryId;
      setState(nextIds, nextPrimary, nextParts, nextDescriptors);
      return { status: "toggled-off", id, primaryId: nextPrimary };
    }
    const part = typeof target === "object" && target?.part ? target.part : { type: "row" };
    describe(id, target, target?.descriptor);
    setState([...ids, id], id, { ...parts, [id]: part }, descriptors);
    return { status: "selected", id, primaryId: id };
  };

  const selectHit = (hit, { additive = false } = {}) => {
    const target = nodeTargetForHit(hit);
    return select(target ? { ...target, descriptor: hitDescriptor(hit) } : null, { additive });
  };

  const pickAtPoint = (scene, point, opts = {}) => {
    const hits = hitTestPlanAll(scene, point, opts);
    const hit = hits.length ? hits[0] : null;
    return { hit, target: nodeTargetForHit(hit), hits };
  };

  const selectAtPoint = (scene, point, { additive = false, ...opts } = {}) =>
    selectHit(pickAtPoint(scene, point, opts).hit, { additive });

  const clear = () => {
    if (!ids.length && primaryId === null) return { status: "empty" };
    setState([], null, {}, {});
    return { status: "cleared" };
  };

  const isSelected = (id) => has(id);

  const entries = () =>
    ids.map((id) => ({
      ...(descriptors[id] || { id, kind: parseSceneNodeId(id)?.kind ?? null }),
      id,
      part: parts[id] || { type: "row" },
      primary: id === primaryId,
    }));

  // Tree-order cycling. dir ±1; with nothing selected +1 picks the first
  // node, -1 the last. Wraps. Returns the node id now primary/only.
  const cycle = (scene, direction = 1) => {
    const tree = buildSceneTree(scene);
    const order = tree.order.filter((id) => tree.nodes.get(id)?.selectable !== false);
    if (!order.length) return { status: "empty", id: null };
    const dir = direction < 0 ? -1 : 1;
    let next;
    if (!primaryId || !order.includes(primaryId)) {
      next = dir > 0 ? order[0] : order[order.length - 1];
    } else {
      const i = order.indexOf(primaryId);
      next = order[(i + dir + order.length) % order.length];
    }
    const n = tree.nodes.get(next);
    describe(next, { id: next, kind: n?.kind }, n ? {
      collection: n.collection, index: n.index, key: n.key,
      componentId: n.componentId, label: n.label, parentId: n.parentId,
      segmentIndex: n.segmentIndex ?? null, signIndex: n.signIndex ?? null,
    } : undefined);
    setState([next], next, { [next]: { type: "row" } }, descriptors);
    return { status: "cycled", id: next, label: n?.label ?? null };
  };

  // Keyboard seam — returns what it did so the consumer can preventDefault
  // and route the delete hook through its own commit path.
  const applyKey = (event, scene) => {
    const act = selectionKeyAction(event);
    if (!act) return null;
    if (act.action === "cycle") return cycle(scene, act.direction);
    if (act.action === "clear") { clear(); return { status: "cleared" }; }
    if (act.action === "delete-request") {
      return { status: "delete-request", entries: entries() };
    }
    return null;
  };

  // Reconcile the selection against a fresh scene: exact-id keeps (a
  // positional `index:` id still existing means the positional row still
  // exists — same-identity rule), component/legacy ids survive reorders,
  // index-refs upgrade to minted component ids, stale parts downgrade.
  const reconcile = (scene) => {
    const tree = buildSceneTree(scene);
    const nextIds = [];
    const nextParts = {};
    const nextDescriptors = {};
    const dropped = [];
    const remapped = {};
    const downgraded = [];
    const seen = new Set();

    const adopt = (oldId, newId, node, part) => {
      if (seen.has(newId)) { dropped.push(oldId); return; }
      seen.add(newId);
      nextIds.push(newId);
      nextParts[newId] = part;
      nextDescriptors[newId] = {
        id: newId, kind: node?.kind ?? null, collection: node?.collection ?? null,
        index: node?.index ?? null, key: node?.key ?? null,
        componentId: node?.componentId ?? null, label: node?.label ?? null,
        parentId: node?.parentId ?? null,
        segmentIndex: node?.segmentIndex ?? null, signIndex: node?.signIndex ?? null,
      };
      if (newId !== oldId) remapped[oldId] = newId;
    };

    const sanitizePart = (id, node, part) => {
      if (!part || part.type === "row") return { type: "row" };
      if (part.type === "vertex" && Number.isInteger(part.vertexIndex)) {
        // wall vertex — vertexIndex is an AUTHORED outline index, so
        // revalidate against the authored point count (not the filtered
        // valid-vertex count the geometry helpers report).
        const w = node?.collection === "walls" ? sceneCollections(scene).walls[node.index] : null;
        const authored = Array.isArray(w?.shape?.points) ? w.shape.points.length : 0;
        if (part.vertexIndex >= 0 && part.vertexIndex < authored) return part;
        downgraded.push(id);
        return { type: "row" };
      }
      if (part.type === "segment") {
        if (node?.kind === "wall-segment" && node.segmentIndex === part.segmentIndex) return part;
        downgraded.push(id);
        return { type: "row" };
      }
      return part;
    };

    for (const oldId of ids) {
      if (tree.nodes.has(oldId)) {
        const node = tree.nodes.get(oldId);
        adopt(oldId, oldId, node, sanitizePart(oldId, node, parts[oldId]));
        continue;
      }
      // Upgrade path: `index:` sub-refs (segment/sign) whose row gained a
      // component id — same wall/pole + same position, minted id.
      const parsed = parseSceneNodeId(oldId);
      if (parsed && (parsed.kind === "wall-segment" || parsed.kind === "pole-sign") && parsed.ref?.startsWith("index:")) {
        const res = resolveSceneNode(scene, oldId);
        if (res) {
          const parentKey = parsed.key;
          const sub = parsed.kind === "wall-segment"
            ? res.segment?.component_id
            : res.sign?.component_id;
          const newId = parsed.kind === "wall-segment"
            ? sceneNodeId.wallSegment(parentKey, subRef(sub ?? res.segment?.component_id, res.segmentIndex))
            : sceneNodeId.poleSign(parentKey, subRef(sub ?? res.sign?.component_id, res.signIndex));
          if (tree.nodes.has(newId)) {
            adopt(oldId, newId, tree.nodes.get(newId), sanitizePart(newId, tree.nodes.get(newId), parts[oldId]));
            continue;
          }
        }
      }
      dropped.push(oldId);
    }

    const nextPrimary = primaryId && seen.has(primaryId)
      ? primaryId
      : primaryId && remapped[primaryId] && seen.has(remapped[primaryId])
        ? remapped[primaryId]
        : nextIds[nextIds.length - 1] ?? null;

    // Descriptor drift counts too — a reorder keeps component ids but
    // changes index/label snapshots the properties panel reads.
    const descChanged =
      nextIds.some((id) => JSON.stringify(nextDescriptors[id]) !== JSON.stringify(descriptors[id])) ||
      Object.keys(nextDescriptors).length !== Object.keys(descriptors).length;
    const changed =
      dropped.length > 0 || Object.keys(remapped).length > 0 ||
      nextIds.length !== ids.length || nextIds.some((id, i) => id !== ids[i]) ||
      nextPrimary !== primaryId || downgraded.length > 0 || descChanged;
    if (changed) {
      setState(nextIds, nextPrimary, nextParts, nextDescriptors);
      return { status: "reconciled", kept: [...nextIds], dropped, remapped, downgraded };
    }
    return { status: "unchanged", kept: [...nextIds], dropped: [], remapped: {}, downgraded: [] };
  };

  // ------------------------------------------------------------------
  // Marquee (rubber-band) — transient gesture state for the renderer,
  // committed against the live scene.
  // ------------------------------------------------------------------

  const beginMarquee = ({ point, additive = false } = {}) => {
    const p = planPointOf(point);
    if (!p) return { status: "invalid" };
    marquee = { start: p, current: p, additive: additive === true };
    emit();
    return { status: "open" };
  };

  const updateMarquee = (point) => {
    if (!marquee) return { status: "no-marquee" };
    const p = planPointOf(point);
    if (!p) return { status: "invalid" };
    marquee = { ...marquee, current: p };
    emit();
    return { status: "updated" };
  };

  // Commit. `empty` is the caller's click verdict (release inside the slop
  // threshold): additive keeps the selection untouched, plain clears it —
  // the empty-space-click rule. A real region picks objectsInRegion and
  // either replaces or unions with the existing selection.
  const commitMarquee = (scene, { mode = "intersect", empty = false } = {}) => {
    if (!marquee) return { status: "no-marquee" };
    const m = marquee;
    marquee = null;
    if (empty) {
      emit();
      if (!m.additive) { clear(); return { status: "cleared" }; }
      return { status: "kept" };
    }
    const region = regionFromPoints(m.start, m.current);
    const picked = sceneObjectsInRegion(scene, region, { mode });
    if (m.additive) {
      const nextIds = [...ids];
      const nextParts = { ...parts };
      const nextDescriptors = { ...descriptors };
      const tree = buildSceneTree(scene);
      for (const id of picked) {
        if (nextIds.includes(id)) continue;
        nextIds.push(id);
        nextParts[id] = { type: "row" };
        const n = tree.nodes.get(id);
        nextDescriptors[id] = descriptorFor(
          { id, kind: n?.kind },
          { collection: n?.collection, index: n?.index, key: n?.key, componentId: n?.componentId, label: n?.label, parentId: n?.parentId },
        );
      }
      const nextPrimary = picked.length ? picked[picked.length - 1] : primaryId;
      setState(nextIds, nextPrimary, nextParts, nextDescriptors);
      return { status: "marquee", ids: [...nextIds], picked, additive: true };
    }
    const tree = buildSceneTree(scene);
    const nextDescriptors = {};
    for (const id of picked) {
      const n = tree.nodes.get(id);
      nextDescriptors[id] = descriptorFor(
        { id, kind: n?.kind },
        { collection: n?.collection, index: n?.index, key: n?.key, componentId: n?.componentId, label: n?.label, parentId: n?.parentId },
      );
    }
    const nextParts = {};
    for (const id of picked) nextParts[id] = { type: "row" };
    setState(picked, picked[picked.length - 1] ?? null, nextParts, nextDescriptors);
    return { status: "marquee", ids: [...picked], picked, additive: false };
  };

  const cancelMarquee = () => {
    if (!marquee) return { status: "no-marquee" };
    marquee = null;
    emit();
    return { status: "cancelled" };
  };

  const getState = () => ({
    stateVersion: version,
    ids: [...ids],
    count: ids.length,
    primaryId,
    primary: primaryId ? { ...(descriptors[primaryId] || { id: primaryId }), id: primaryId, part: parts[primaryId] || { type: "row" } } : null,
    marquee: marquee ? { ...marquee, start: { ...marquee.start }, current: { ...marquee.current } } : null,
  });

  const subscribe = (fn) => {
    if (typeof fn !== "function") return () => { };
    listeners.add(fn);
    return () => { listeners.delete(fn); };
  };

  return {
    // queries
    isSelected, entries, getState, subscribe,
    // mutation
    select, setSelection, selectHit, selectAtPoint, clear, cycle, applyKey,
    // scene-facing
    pickAtPoint, reconcile,
    // marquee
    beginMarquee, updateMarquee, commitMarquee, cancelMarquee,
    get stateVersion() { return version; },
    get primaryId() { return primaryId; },
  };
}

// O-040 (CMP-C09) — foundation scene edit history (stroke-level undo).
//
// Pure, DOM-free undo/redo store for scene edits. One continuous gesture —
// a pointer drag begin→moves→commit, a keyboard nudge burst, or a
// multi-commit paint-style stroke — records as ONE undoable command. The
// store never mutates the scene itself: consumers apply returned patch
// payloads through their normal commit path and report the live scene's
// geometry anchor back via observe(), so every undo is CAS-gated against
// the scene it was recorded on. An external write (another panel, a
// Builder sync, a concurrent save adopting a new revision) detaches the
// chain instead of letting undo resurrect stale geometry over it.
//
// Terminology:
//   * edit    — an atomic committed change record { before, after,
//               beforeAnchor, afterAnchor, ... }. `before`/`after` are
//               caller-shaped restore values (for canvas item moves,
//               { x_inches, z_inches } patch-shaped).
//   * stroke  — a multi-commit gesture aggregated between beginStroke and
//              commitStroke (paint cells, future vertex/segment drags that
//              land sub-edits continuously). A pointer drag commits exactly
//              once, so the canvas records it via recordEdit — the
//              one-command outcome is identical.
//   * anchor  — opaque caller token fingerprinting the scene's editable
//              geometry (see sceneLayoutAnchor). Entries chain
//              beforeAnchor → afterAnchor; undo applies only while the
//              live anchor equals the head entry's afterAnchor.
//   * detached — recorded entries whose chain was broken below them by an
//              external write. Kept for honest reporting, never applied;
//              pruned when the undo cursor reaches the boundary.
//
// Anchor discipline is all-or-nothing per store: once anchored (first
// observe() or first anchored record), edits lacking BOTH anchors are
// refused with 'ignored-unanchored' — an unverifiable edit must never sit
// inside a CAS-gated chain. Unanchored stores (never observed) work as a
// plain undo stack.
//
// Coalescing: consecutive committed edits sharing a non-null coalesceKey
// merge into one entry while the merge stays inside coalesceWindowMs of the
// last sub-edit AND the chain still links (incoming beforeAnchor === top
// afterAnchor). The key is caller-computed (the input seam's
// sceneEditCoalesceKey maps a keyboard burst on one row to one identity);
// drags pass null — one gesture is already one command.
//
// Mount sketch (page-owned, see MOUNT-ANCHORS.md):
//   const ref = useRef(null); if (!ref.current) ref.current = createSceneHistory();
//   useSyncExternalStore(ref.current.subscribe, () => ref.current.getState().stateVersion);
//   <FoundationLayoutCanvas ... sceneHistory={ref.current} />
//   const undo = () => ref.current.undo(sceneLayoutAnchor(items), (rev) => apply(rev) !== false);

import { layoutItemFingerprint } from "./foundationLayoutModel";

const fin = (v) => typeof v === "number" && Number.isFinite(v);

export const SCENE_HISTORY_CAPACITY = 100;
export const SCENE_HISTORY_COALESCE_WINDOW_MS = 1200;

// ---------------------------------------------------------------------------
// Scene geometry anchors
// ---------------------------------------------------------------------------

// Walls carry their plan geometry in shape.points (+ closed), not the item
// footprint/position fields layoutItemFingerprint reads — their anchor part
// fingerprints the authored outline directly.
const wallAnchorPart = (wall) => JSON.stringify({
  pts: Array.isArray(wall?.shape?.points) ? wall.shape.points : null,
  closed: wall?.shape?.closed === true,
});

// Geometry-only CAS token for the whole editable scene. Rows fingerprint
// with the same field set the drag guards use (position validity/type/
// corner/footprint/rotation for items and poles, outline for walls); the
// join preserves row count and order, so any geometric change — move,
// resize, rotate, insert, delete, or a reorder of differently-shaped rows —
// yields a different anchor. Two anchor-relevant properties are deliberate:
//   * component ids/keys are EXCLUDED — normalization minting a component_id
//     does not move geometry and must not look like an external write.
//   * non-geometry fields (labels, prices, materials) are EXCLUDED — a cost
//     or text edit must not invalidate position undo.
// `scene` accepts an items array (canvas shape) or { items, poles, walls }.
// Deterministic: same scene in → identical string out.
export function sceneLayoutAnchor(scene) {
  const s = Array.isArray(scene) ? { items: scene } : (scene && typeof scene === "object" ? scene : {});
  const fp = (rows, f) => (Array.isArray(rows) ? rows.map(f).join(",") : "");
  return `i:${fp(s.items, layoutItemFingerprint)}|p:${fp(s.poles, layoutItemFingerprint)}|w:${fp(s.walls, wallAnchorPart)}`;
}

// Rows with one row's fields patched — the anchor formula for "the scene
// with only this row's geometry changed". Consumers compute before/after
// anchors against the CURRENT rows with only the target swapped, so an
// interleaved write to a different row is preserved inside the entry
// instead of detaching it.
export function rowsWithPatch(rows, index, patch) {
  if (!Array.isArray(rows)) return rows;
  if (typeof index !== "number" || index < 0 || index >= rows.length || !patch) return rows;
  return rows.map((r, i) => (i === index ? { ...r, ...patch } : r));
}

// ---------------------------------------------------------------------------
// History store
// ---------------------------------------------------------------------------

const hasAnchor = (v) => v !== undefined && v !== null;

export function createSceneHistory({
  capacity = SCENE_HISTORY_CAPACITY,
  coalesceWindowMs = SCENE_HISTORY_COALESCE_WINDOW_MS,
  now = () => Date.now(),
  equal,
} = {}) {
  const eq = typeof equal === "function"
    ? equal
    : (a, b) => JSON.stringify(a) === JSON.stringify(b);
  const cap = fin(capacity) && capacity >= 1 ? Math.floor(capacity) : SCENE_HISTORY_CAPACITY;
  // 0 disables coalescing; Infinity merges every adjacent same-key edit.
  const window_ = coalesceWindowMs === Infinity
    ? Infinity
    : fin(coalesceWindowMs) && coalesceWindowMs >= 0 ? coalesceWindowMs : SCENE_HISTORY_COALESCE_WINDOW_MS;
  const clock = typeof now === "function" ? now : () => Date.now();

  // State. `detached` counts unreachable entries at the BOTTOM of past —
  // entries at index < detached can never apply again. `currentAnchor` is
  // the anchor the live undo chain expects the scene to hold right now.
  let past = [];
  let future = [];
  let open = null;
  let detached = 0;
  let currentAnchor;
  let anchored = false;
  let seq = 0;
  let stateVersion = 0;
  const listeners = new Set();

  const emit = () => {
    stateVersion += 1;
    for (const fn of [...listeners]) {
      try { fn(); } catch { /* listener faults never break the store */ }
    }
  };

  const info = (e, i) => ({
    id: e.id,
    kind: e.kind ?? null,
    method: e.method ?? null,
    label: e.label ?? null,
    target: e.target ?? null,
    moves: e.moves ?? 1,
    openedAt: e.openedAt ?? null,
    committedAt: e.committedAt ?? null,
    lastAt: e.lastAt ?? null,
    detached: typeof i === "number" ? i < detached : false,
  });

  // Every recorded entry below the current head is unreachable after an
  // external write — mark the boundary, drop redo (a redo can never cross a
  // rewrite), and cancel any in-flight stroke (its own commits may have
  // landed on a different base). Returns true when visible state changed.
  const markDetached = () => {
    let changed = false;
    if (open) { open = null; changed = true; }
    if (future.length) { future = []; changed = true; }
    if (detached !== past.length) { detached = past.length; changed = true; }
    return changed;
  };

  const boundStacks = () => {
    while (past.length > cap) {
      past.shift();
      if (detached > 0) detached -= 1;
    }
    while (future.length > cap) future.pop();
  };

  // Head-entry liveness, non-mutating: the top of past must sit above the
  // detached boundary AND chain to the tracked anchor.
  const topApplies = () =>
    past.length > detached &&
    (!hasAnchor(past[past.length - 1].afterAnchor) || past[past.length - 1].afterAnchor === currentAnchor);
  const topRedoApplies = () =>
    future.length > 0 &&
    (!hasAnchor(future[0].beforeAnchor) || future[0].beforeAnchor === currentAnchor);

  const seedAnchor = (anchor) => {
    if (!anchored && hasAnchor(anchor)) { anchored = true; currentAnchor = anchor; }
  };

  // Anchor reconciliation shared by record paths. An edit asserting a base
  // different from the tracked head means the scene moved outside the
  // stroke channel — detach before the new edit joins the chain.
  const reconcileBase = (beforeAnchor) => {
    if (anchored && hasAnchor(beforeAnchor) && beforeAnchor !== currentAnchor) return markDetached();
    return false;
  };

  // ------------------------------------------------------------------
  // Observation + lifecycle
  // ------------------------------------------------------------------

  const observe = (anchor) => {
    if (!hasAnchor(anchor)) return { status: "unanchored" };
    if (!anchored) { anchored = true; currentAnchor = anchor; return { status: "anchored" }; }
    if (anchor === currentAnchor) return { status: "current" };
    const changed = markDetached();
    currentAnchor = anchor;
    if (changed) emit();
    return { status: "detached", detached };
  };

  const clear = (anchor) => {
    past = []; future = []; open = null; detached = 0;
    anchored = false; currentAnchor = undefined;
    if (hasAnchor(anchor)) { anchored = true; currentAnchor = anchor; }
    emit();
    return { status: "cleared" };
  };

  // ------------------------------------------------------------------
  // Atomic edits (one committed change = one command)
  // ------------------------------------------------------------------

  const recordEdit = (edit = {}) => {
    const at = fin(edit.at) ? edit.at : clock();
    if (open) commitStroke({ at }); // interleaved atomic commit never orphans landed sub-edits
    // Anchored stores fail closed on unverifiable edits.
    if (anchored && !(hasAnchor(edit.beforeAnchor) && hasAnchor(edit.afterAnchor))) {
      return { status: "ignored-unanchored" };
    }
    // A record that provably changed nothing is not history.
    if (hasAnchor(edit.beforeAnchor) && edit.beforeAnchor === edit.afterAnchor && eq(edit.before, edit.after)) {
      return { status: "ignored-noop" };
    }
    seedAnchor(edit.beforeAnchor);
    const detachedBefore = reconcileBase(edit.beforeAnchor) ? detached : null;

    const key = edit.coalesceKey ?? null;
    const top = past[past.length - 1];
    const mergeable =
      key != null && top && past.length - 1 >= detached &&
      top.coalesceKey === key && top.mergeable !== false &&
      (!hasAnchor(edit.beforeAnchor) || !hasAnchor(top.afterAnchor) || edit.beforeAnchor === top.afterAnchor) &&
      window_ > 0 && at - top.lastAt <= window_;
    if (mergeable) {
      top.after = edit.after;
      if (hasAnchor(edit.afterAnchor)) { top.afterAnchor = edit.afterAnchor; currentAnchor = edit.afterAnchor; }
      top.lastAt = at;
      top.moves = (top.moves ?? 1) + 1;
      if (edit.label) top.label = edit.label;
      future = [];
      // A burst that returns to its start point cancels itself out — drop
      // the entry rather than leaving a command that provably changes
      // nothing ("sensible history", not a no-op button).
      if (hasAnchor(top.beforeAnchor) && top.beforeAnchor === top.afterAnchor && eq(top.before, top.after)) {
        past.pop();
        emit();
        return { status: "merged-noop", detachedBefore };
      }
      emit();
      return { status: "merged", entry: top, detachedBefore };
    }

    const entry = {
      id: (seq += 1),
      kind: edit.kind ?? null,
      method: edit.method ?? null,
      label: edit.label ?? null,
      target: edit.target ?? null,
      coalesceKey: key,
      before: edit.before,
      after: edit.after,
      beforeAnchor: edit.beforeAnchor,
      afterAnchor: edit.afterAnchor,
      mergeable: edit.mergeable,
      openedAt: at,
      committedAt: at,
      lastAt: at,
      moves: 1,
    };
    past.push(entry);
    boundStacks();
    future = [];
    if (hasAnchor(edit.afterAnchor)) currentAnchor = edit.afterAnchor;
    emit();
    return { status: "recorded", entry, detachedBefore };
  };

  // ------------------------------------------------------------------
  // Multi-commit strokes (paint/drag gestures that land sub-edits)
  // ------------------------------------------------------------------

  const beginStroke = (opts = {}) => {
    const at = fin(opts.at) ? opts.at : clock();
    if (open) commitStroke({ at }); // a new gesture never orphans the prior one's landed work
    if (anchored && !(hasAnchor(opts.beforeAnchor))) return { status: "ignored-unanchored" };
    seedAnchor(opts.beforeAnchor);
    const detachedBefore = reconcileBase(opts.beforeAnchor) ? detached : null;
    open = {
      id: (seq += 1),
      kind: opts.kind ?? null,
      method: opts.method ?? null,
      label: opts.label ?? null,
      target: opts.target ?? null,
      coalesceKey: opts.coalesceKey ?? null,
      before: opts.before,
      after: undefined,
      beforeAnchor: opts.beforeAnchor,
      afterAnchor: undefined,
      mergeable: opts.mergeable,
      openedAt: at,
      lastAt: at,
      moves: 0,
    };
    emit();
    return { status: "open", stroke: open, detachedBefore };
  };

  const extendStroke = ({ after, afterAnchor, at } = {}) => {
    if (!open) return { status: "no-stroke" };
    const t = fin(at) ? at : clock();
    if (after !== undefined) open.after = after;
    if (hasAnchor(afterAnchor)) { open.afterAnchor = afterAnchor; currentAnchor = afterAnchor; }
    open.lastAt = t;
    open.moves = (open.moves ?? 0) + 1;
    emit();
    return { status: "extended", stroke: open };
  };

  const commitStroke = ({ after, afterAnchor, label, at } = {}) => {
    if (!open) return { status: "no-stroke" };
    const t = fin(at) ? at : clock();
    const s = open;
    open = null;
    if (after !== undefined) s.after = after;
    if (hasAnchor(afterAnchor)) { s.afterAnchor = afterAnchor; currentAnchor = afterAnchor; }
    if (label) s.label = label;
    // A stroke that landed nothing is not a command — that verdict stands
    // regardless of anchors.
    if (s.after === undefined) { emit(); return { status: "cancelled-empty" }; }
    // Anchored stores fail closed on unverifiable edits — a stroke that
    // cannot state the scene it landed on can never be CAS-undone.
    if (anchored && !hasAnchor(s.afterAnchor)) { emit(); return { status: "ignored-unanchored" }; }
    if (hasAnchor(s.beforeAnchor) && s.beforeAnchor === s.afterAnchor && eq(s.before, s.after)) {
      emit();
      return { status: "ignored-noop" };
    }
    const entry = { ...s, committedAt: t, lastAt: t, moves: Math.max(1, s.moves ?? 0) };
    past.push(entry);
    boundStacks();
    future = [];
    emit();
    return { status: "recorded", entry };
  };

  const cancelStroke = () => {
    if (!open) return { status: "no-stroke" };
    open = null;
    emit();
    return { status: "cancelled" };
  };

  // ------------------------------------------------------------------
  // Traversal
  // ------------------------------------------------------------------
  // `apply` is the consumer's commit path: called with the revert/reapply
  // payload INSIDE the transition so a refused commit leaves the stacks
  // untouched ('rejected'). Anything returned other than === false counts
  // as applied; omitting apply performs the transition unconditionally —
  // consumers with a fallible commit path must pass it.

  const traverse = (direction, anchor, apply) => {
    if (open) return { status: "busy" };
    if (hasAnchor(anchor) && anchored && anchor !== currentAnchor) {
      return { status: "anchor-mismatch" };
    }
    const applies = direction === "undo" ? topApplies : topRedoApplies;
    if (!applies()) {
      const source = direction === "undo" ? past : future;
      if (!source.length || (direction === "undo" && past.length <= detached)) {
        // Reachable history exhausted. A dead tail exists only for undo —
        // prune it on contact so memory stays bounded.
        if (direction === "undo" && past.length) {
          past = [];
          detached = 0;
          emit();
          return { status: "stale" };
        }
        return { status: source.length ? "stale" : "empty" };
      }
      // Head record exists but its chain no longer reaches the live anchor —
      // external drift the observer missed. Same end state as a mismatch:
      // mark everything detached and refuse.
      if (direction === "undo") { if (markDetached()) emit(); return { status: "stale" }; }
      if (future.length) { future = []; emit(); }
      return { status: "stale" };
    }

    const entry = direction === "undo" ? past[past.length - 1] : future[0];
    const patch = direction === "undo" ? entry.before : entry.after;
    const payload = {
      status: "applied",
      direction,
      kind: entry.kind,
      method: entry.method,
      label: entry.label,
      target: entry.target,
      patch,
      entry,
    };
    if (typeof apply === "function") {
      let result;
      try { result = apply(payload); }
      catch { result = false; }
      if (result === false) return { status: "rejected", entry };
    }
    if (direction === "undo") {
      past.pop();
      future.unshift(entry);
      if (hasAnchor(entry.beforeAnchor)) currentAnchor = entry.beforeAnchor;
    } else {
      future.shift();
      past.push(entry);
      if (hasAnchor(entry.afterAnchor)) currentAnchor = entry.afterAnchor;
    }
    emit();
    return payload;
  };

  const undo = (anchor, apply) => traverse("undo", anchor, apply);
  const redo = (anchor, apply) => traverse("redo", anchor, apply);

  // ------------------------------------------------------------------
  // Inspection (UI state + diagnostics)
  // ------------------------------------------------------------------

  const peekUndo = () => (topApplies() ? info(past[past.length - 1]) : null);
  const peekRedo = () => (topRedoApplies() ? info(future[0]) : null);

  const entries = () => ({
    past: past.map((e, i) => info(e, i)),
    future: future.map((e, i) => ({ ...info(e), detached: false })),
    detached,
    open: open ? info(open) : null,
  });

  const getState = () => ({
    stateVersion,
    capacity: cap,
    coalesceWindowMs: window_,
    busy: open != null,
    open: open ? info(open) : null,
    canUndo: !open && topApplies(),
    canRedo: !open && topRedoApplies(),
    undoDepth: Math.max(0, past.length - detached),
    redoDepth: future.length,
    detached,
    undoLabel: peekUndo()?.label ?? null,
    redoLabel: peekRedo()?.label ?? null,
  });

  const subscribe = (fn) => {
    if (typeof fn !== "function") return () => { };
    listeners.add(fn);
    return () => { listeners.delete(fn); };
  };

  return {
    // observation + lifecycle
    observe, clear,
    // recording
    recordEdit, beginStroke, extendStroke, commitStroke, cancelStroke,
    // traversal
    undo, redo,
    // inspection + subscription
    peekUndo, peekRedo, entries, getState, subscribe,
    get stateVersion() { return stateVersion; },
    get currentAnchor() { return currentAnchor; },
    get anchored() { return anchored; },
  };
}
